insert into questoes (banco, origem_id, categoria, contexto, enunciado, imagem_url, alternativas, correta, explicacao) values
('anac', '12fd09bd-96ee-4808-a819-cd74d384cf5e', 'Segurança e Emergência', null, 'A regra mais importante em qualquer situação de emergência é:', null, '[{"letra": "A", "texto": "Chamar o comandante", "imagem_url": null}, {"letra": "B", "texto": "Manter a calma e avaliar a situação", "imagem_url": null}, {"letra": "C", "texto": "Acionar os alarmes", "imagem_url": null}, {"letra": "D", "texto": "Evacuar imediatamente", "imagem_url": null}]'::jsonb, 'B', null),
('anac', '62056151-fabc-4c87-9f26-006598aed913', 'Segurança e Emergência', null, 'Em caso de despressurização da cabine, as máscaras de oxigênio cairão automaticamente quando a altitude da cabine atingir:', null, '[{"letra": "A", "texto": "10.000 pés", "imagem_url": null}, {"letra": "B", "texto": "14.000 pés", "imagem_url": null}, {"letra": "C", "texto": "12.000 pés", "imagem_url": null}, {"letra": "D", "texto": "16.000 pés", "imagem_url": null}]'::jsonb, 'B', null),
('anac', '9e157a89-3a23-479c-a311-f9fa06fdf1f4', 'Segurança e Emergência', null, 'O extintor de água é mais eficaz para combater incêndios de classe:', null, '[{"letra": "A", "texto": "A", "imagem_url": null}, {"letra": "B", "texto": "D", "imagem_url": null}, {"letra": "C", "texto": "C", "imagem_url": null}, {"letra": "D", "texto": "B", "imagem_url": null}]'::jsonb, 'A', null),
('anac', '98526187-254e-441b-be80-58e99c6602f0', 'Segurança e Emergência', null, 'Durante um pouso de emergência na água, os passageiros devem:', null, '[{"letra": "A", "texto": "Inflar o colete salva-vidas dentro da aeronave", "imagem_url": null}, {"letra": "B", "texto": "Inflar o colete após sair da aeronave", "imagem_url": null}, {"letra": "C", "texto": "Não usar colete salva-vidas", "imagem_url": null}, {"letra": "D", "texto": "Pular na água imediatamente", "imagem_url": null}]'::jsonb, 'B', null),
('anac', 'a781e0b3-ea7d-4be1-aa7e-d9da4de1911a', 'Segurança e Emergência', null, 'A posição de impacto protege principalmente:', null, '[{"letra": "A", "texto": "Apenas os braços", "imagem_url": null}, {"letra": "B", "texto": "A cabeça, pescoço e coluna", "imagem_url": null}, {"letra": "C", "texto": "Apenas as pernas", "imagem_url": null}, {"letra": "D", "texto": "Apenas o tórax", "imagem_url": null}]'::jsonb, 'B', null),
('anac', '4a492a93-e363-4365-8a03-6ab1651e3af9', 'Legislação Aeronáutica', null, 'A ANAC é responsável por:', null, '[{"letra": "A", "texto": "Regulamentar e fiscalizar a aviação civil", "imagem_url": null}, {"letra": "B", "texto": "Operar aeroportos", "imagem_url": null}, {"letra": "C", "texto": "Treinar pilotos", "imagem_url": null}, {"letra": "D", "texto": "Fabricar aeronaves", "imagem_url": null}]'::jsonb, 'A', null),
('anac', 'a7846cd6-4e1b-4e3e-b37f-73906f755ccb', 'Legislação Aeronáutica', null, 'O RBAC 67 trata sobre:', null, '[{"letra": "A", "texto": "Aeródromos", "imagem_url": null}, {"letra": "B", "texto": "Licenças e certificados de comissários", "imagem_url": null}, {"letra": "C", "texto": "Manutenção de aeronaves", "imagem_url": null}, {"letra": "D", "texto": "Operações de voo", "imagem_url": null}]'::jsonb, 'B', null),
('anac', '547b7a28-647d-4df7-8fd8-e807472d1abf', 'Primeiros Socorros', null, 'A sequência correta da RCP (Reanimação Cardiopulmonar) é:', null, '[{"letra": "A", "texto": "30 compressões e 2 ventilações", "imagem_url": null}, {"letra": "B", "texto": "5 compressões e 1 ventilação", "imagem_url": null}, {"letra": "C", "texto": "15 compressões e 2 ventilações", "imagem_url": null}, {"letra": "D", "texto": "10 compressões e 2 ventilações", "imagem_url": null}]'::jsonb, 'A', null),
('anac', '1f04e882-6fec-446c-978c-00fcbc0b3760', 'Primeiros Socorros', null, 'Em caso de hemorragia grave, a primeira ação deve ser:', null, '[{"letra": "A", "texto": "Aplicar torniquete", "imagem_url": null}, {"letra": "B", "texto": "Lavar o ferimento", "imagem_url": null}, {"letra": "C", "texto": "Dar água ao paciente", "imagem_url": null}, {"letra": "D", "texto": "Fazer compressão direta no ferimento", "imagem_url": null}]'::jsonb, 'D', null),
('anac', '8cf91df1-39cb-48bd-8a05-ff91f783af1d', 'Primeiros Socorros', null, 'A manobra de Heimlich é utilizada em casos de:', null, '[{"letra": "A", "texto": "Queimadura", "imagem_url": null}, {"letra": "B", "texto": "Fratura", "imagem_url": null}, {"letra": "C", "texto": "Parada cardíaca", "imagem_url": null}, {"letra": "D", "texto": "Engasgo/obstrução de vias aéreas", "imagem_url": null}]'::jsonb, 'D', null),
('anac', 'ecf9ee6e-9e1d-4fd2-98fc-09a37fa37f7a', 'Conhecimentos Técnicos', null, 'A pressurização da cabine serve para:', null, '[{"letra": "A", "texto": "Reduzir ruídos", "imagem_url": null}, {"letra": "B", "texto": "Manter condições adequadas de oxigênio em grandes altitudes", "imagem_url": null}, {"letra": "C", "texto": "Filtrar o ar", "imagem_url": null}, {"letra": "D", "texto": "Resfriar a cabine", "imagem_url": null}]'::jsonb, 'B', null),
('anac', '15294e7d-5695-4efb-bb8b-6e3fb55dde50', 'Conhecimentos Técnicos', null, 'Os motores a jato funcionam baseados no princípio de:', null, '[{"letra": "A", "texto": "Combustão interna", "imagem_url": null}, {"letra": "B", "texto": "Pressão hidráulica", "imagem_url": null}, {"letra": "C", "texto": "Energia elétrica", "imagem_url": null}, {"letra": "D", "texto": "Ação e reação", "imagem_url": null}]'::jsonb, 'D', null),
('anac', '757b6e69-63c9-49df-a21e-26ec42e6aa59', 'Conhecimentos Técnicos', null, 'O trem de pouso principal suporta aproximadamente:', null, '[{"letra": "A", "texto": "90% do peso da aeronave", "imagem_url": null}, {"letra": "B", "texto": "50% do peso da aeronave", "imagem_url": null}, {"letra": "C", "texto": "10% do peso da aeronave", "imagem_url": null}, {"letra": "D", "texto": "30% do peso da aeronave", "imagem_url": null}]'::jsonb, 'A', null),
('anac', '9de1edc2-d9f0-4a53-9a71-bbb90e4f4919', 'Primeiros Socorros', null, 'CICLOS CONTÍNUOS DE COMPRESSÕES TORÁCICAS, ABERTURA DAS VIAS AÉREAS E INSUFLAÇÕES, SÃO PROCEDIMENTOS ADOTADOS EM CASO DE', null, '[{"letra": "A", "texto": "CHOQUE HIPOVOLÊMICO", "imagem_url": null}, {"letra": "B", "texto": "DERRAME CEREBRAL", "imagem_url": null}, {"letra": "C", "texto": "ATAQUE EPILÉPTICO", "imagem_url": null}, {"letra": "D", "texto": "PARADA CÁRDIO-RESPIRATÓRIA", "imagem_url": null}]'::jsonb, 'D', null),
('anac', 'e7615992-8202-4869-8207-3d91334a02a9', 'Primeiros Socorros', null, 'DAS ALTERNATIVAS ABAIXO, A QUE TRADUZ O TERMO HIGIENE:', null, '[{"letra": "A", "texto": "cuidados diários como: asseio corporal, alimentação e viagens", "imagem_url": null}, {"letra": "B", "texto": "preservar a saúde através de medidas políticas", "imagem_url": null}, {"letra": "C", "texto": "prevenção e limpeza, evitando as doenças infecto-contagiosas", "imagem_url": null}, {"letra": "D", "texto": "aplicação de medidas que visam prevenir doenças e preservar a saúde", "imagem_url": null}]'::jsonb, 'D', null),
('anac', '9a213468-e8d5-4f46-b592-0776166023d6', 'Segurança e Emergência', null, 'O MAIOR PERIGO COM QUE SE DEFRONTAM OS SOBREVIVENTES EM UMA FLORESTA TROPICAL SÃO OS (AS)', null, '[{"letra": "A", "texto": "CROCODILEANOS", "imagem_url": null}, {"letra": "B", "texto": "INSETOS CAUSADORES DE MOLÉSTIAS", "imagem_url": null}, {"letra": "C", "texto": "OFÍDIOS", "imagem_url": null}, {"letra": "D", "texto": "ANIMAIS ONÍVOROS", "imagem_url": null}]'::jsonb, 'B', null),
('anac', '2b93326c-a505-470c-9e1a-1c3ac8ac53c2', 'Segurança e Emergência', null, 'NOS TOALETES, COM SISTEMA PREVENTIVO DE FOGO, EXISTE UM DISPOSITIVO EM SEU INTERIOR. INDIQUE-O ABAIXO:', null, '[{"letra": "A", "texto": "capuz antifumaça", "imagem_url": null}, {"letra": "B", "texto": "espelho com iluminação de alarme", "imagem_url": null}, {"letra": "C", "texto": "aviso luminoso", "imagem_url": null}, {"letra": "D", "texto": "detector de fumaça", "imagem_url": null}]'::jsonb, 'D', null),
('anac', 'dc40a687-61fe-480b-8569-090f0a1a9b96', 'Segurança e Emergência', null, 'QUANDO HOUVER FALHA NO SISTEMA NORMAL DE ILUMINAÇÃO, NAS AERONAVES EM GERAL, OCORRERÁ QUE:', null, '[{"letra": "A", "texto": "um sistema secundário será acionado", "imagem_url": null}, {"letra": "B", "texto": "os faróis da aeronave serão acesos automaticamente", "imagem_url": null}, {"letra": "C", "texto": "imediatamente todas as luzes de leitura serão acesas", "imagem_url": null}, {"letra": "D", "texto": "as luzes de emergência serão acesas automaticamente", "imagem_url": null}]'::jsonb, 'D', null),
('anac', '529c24ad-43aa-4bd9-8205-1d40303b3a1d', 'Segurança e Emergência', null, 'EM UMA SOBREVIVÊNCIA NA SELVA, DE UM MODO GERAL, OS ALIMENTOS PROCURADOS POR MAMÍFEROS E PÁSSAROS', null, '[{"letra": "A", "texto": "SÃO A ÚLTIMA OPÇÃO DE ALIMENTOS A SEREM CONSUMIDOS", "imagem_url": null}, {"letra": "B", "texto": "SÃO SEMPRE AMARGOS E LEITOSOS", "imagem_url": null}, {"letra": "C", "texto": "PODEM SER INGERIDOS, POIS NÃO APRESENTAM PERIGO", "imagem_url": null}, {"letra": "D", "texto": "PODEM ESTAR CONTAMINADOS", "imagem_url": null}]'::jsonb, 'C', null),
('anac', 'f140d5a3-17a3-4097-8b1d-7c841d5670ff', 'Segurança e Emergência', null, 'NA UTILIZAÇÃO DO EXTINTOR DE ÁGUA PRESSURIZADA, ANTES DE APERTAR O GATILHO, DEVE-SE:', null, '[{"letra": "A", "texto": "verificar a pressão pelo manômetro", "imagem_url": null}, {"letra": "B", "texto": "girar o punho do extintor apara a direita", "imagem_url": null}, {"letra": "C", "texto": "girar o punho do extintor para a esquerda", "imagem_url": null}, {"letra": "D", "texto": "remover a trava de segurança", "imagem_url": null}]'::jsonb, 'D', null),
('anac', '5971c507-ef69-41db-90db-5d7f3bc25d1e', 'Segurança e Emergência', null, 'UM DOS ITENS DA NOSER IAC - SOBRE ABASTECIMENTO DE AERONAVES COM PAX A BORDO, SERÁ:', null, '[{"letra": "A", "texto": "checar os paxs quanto ao encosto da poltrona na posição vertical, mesinhas travadas", "imagem_url": null}, {"letra": "B", "texto": "alocução apropriada sobre o desembarque dos passageiros", "imagem_url": null}, {"letra": "C", "texto": "alocução apropriada sobre os procedimentos e medidas de segurança pertinentes", "imagem_url": null}, {"letra": "D", "texto": "checar e travar as galleys, verificar os cintos de segurança dos paxs", "imagem_url": null}]'::jsonb, 'C', null),
('anac', '532c797b-1cf6-4b7d-b1dc-792d4dace006', 'Segurança e Emergência', null, 'EM REGIÕES DESÉRTICAS, A MELHOR PROTEÇÃO PARA O CALOR DO DIA, É ENCONTRADA:', null, '[{"letra": "A", "texto": "dentro da aeronave", "imagem_url": null}, {"letra": "B", "texto": "em lugares elevados", "imagem_url": null}, {"letra": "C", "texto": "em áreas drenosas", "imagem_url": null}, {"letra": "D", "texto": "à sombra das dunas", "imagem_url": null}]'::jsonb, 'D', null),
('anac', '1bea9cda-e4d8-47b3-87ac-68b7310eb2fa', 'Segurança e Emergência', null, 'O SISTEMA FIXO DE EXTINÇÃO DE INCÊNDIO DOS TOALETES É ACIONADO AUTOMATICAMENTE QUANDO A TEMPERATURA ATINGIR:', null, '[{"letra": "A", "texto": "170ºC", "imagem_url": null}, {"letra": "B", "texto": "70ºF", "imagem_url": null}, {"letra": "C", "texto": "104ºC", "imagem_url": null}, {"letra": "D", "texto": "174ºF", "imagem_url": null}]'::jsonb, 'D', null),
('anac', '807d3f44-337b-4977-beb0-04877fddae6c', 'Primeiros Socorros', null, 'À DEFICIÊNCIA PARCIAL DE FORNECIMENTO DE OXIGÊNIO ÀS CÉLULAS, DÁ-SE O NOME', null, '[{"letra": "A", "texto": "ATROFIA", "imagem_url": null}, {"letra": "B", "texto": "HIPÓXIA", "imagem_url": null}, {"letra": "C", "texto": "ANÓXIA", "imagem_url": null}, {"letra": "D", "texto": "ANEMIA", "imagem_url": null}]'::jsonb, 'B', null),
('anac', '3590712e-224f-46bb-b6cd-88b046c0d401', 'Primeiros Socorros', null, 'A HISTERIA DE CONVERSÃO DEVE SER TRATADA:', null, '[{"letra": "A", "texto": "sempre com amônia", "imagem_url": null}, {"letra": "B", "texto": "sempre com medidas enérgicas e agressivas", "imagem_url": null}, {"letra": "C", "texto": "com respeito, devendo o comissário procurar tranqüilizar o doente", "imagem_url": null}, {"letra": "D", "texto": "com indiferença", "imagem_url": null}]'::jsonb, 'C', null),
('anac', 'f9cea2a7-24e9-4659-acb4-4a97f3c978d5', 'Primeiros Socorros', null, 'A DIMINUIÇÃO SÚBITA DA PRESSÃO ATMOSFÉRICA EM VOO COMPROMETE, PRINCIPALMENTE, O', null, '[{"letra": "A", "texto": "RIM, OUVIDO MÉDIO E PULMÃO", "imagem_url": null}, {"letra": "B", "texto": "FÍGADO, GASES DA CAVIDADE DIGESTIVA E OUVIDO", "imagem_url": null}, {"letra": "C", "texto": "OUVIDO MÉDIO, SEIOS DA FACE E GASES DO APARELHO DIGESTIVO", "imagem_url": null}, {"letra": "D", "texto": "OUVIDO INTERNO, SEIOS DA FACE E BAÇO", "imagem_url": null}]'::jsonb, 'C', null),
('anac', '5c84ea0c-1a62-416c-913b-323d29a99efb', 'Segurança e Emergência', null, 'PARA SE FAZER SINALIZAÇÃO COM CARTUCHOS PIROTÉCNICOS, USA-SE A FUMAÇA:', null, '[{"letra": "A", "texto": "branca de dia e a vermelha, à noite", "imagem_url": null}, {"letra": "B", "texto": "durante o dia e a tocha vermelha à noite", "imagem_url": null}, {"letra": "C", "texto": "vermelha durante o dia e a branca, à noite", "imagem_url": null}, {"letra": "D", "texto": "durante a noite e a tocha vermelha de dia", "imagem_url": null}]'::jsonb, 'B', null),
('anac', '90c48527-615f-4db4-b544-8ce95450b4bd', 'Segurança e Emergência', null, 'INDIQUE O PROCEDIMENTO INICIAL AO SOAR O ALARME DE FUMAÇA DO TOALETE.', null, '[{"letra": "A", "texto": "ENTRAR LOGO NO TOALETE PARA COMBATER O FOGO", "imagem_url": null}, {"letra": "B", "texto": "ABRIR UMA FRESTA OU FURO NA PORTA COM A MACHADINHA E DESCARREGAR UM EXTINTOR DE HALON", "imagem_url": null}, {"letra": "C", "texto": "ABRIR PARCIALMENTE A PORTA PARA OBSERVAR A EXTENSÃO DO FOGO", "imagem_url": null}, {"letra": "D", "texto": "AVALIAR A TEMPERATURA DO TOALETE ATRAVÉS DE CONTATO DO DORSO DA MÃO COM A PORTA", "imagem_url": null}]'::jsonb, 'D', null),
('anac', '24c53420-6d6d-4a28-ab5f-f15b1229eec5', 'Segurança e Emergência', null, 'O FOGO GERA CALOR. O CALOR DESPRENDE VAPORES E GASES QUE SE INFLAMAM, GERANDO MAIS CALOR, MAIS VAPORES E MAIS FOGO. TAL FENÔMENO É CONHECIDO COMO:', null, '[{"letra": "A", "texto": "reação em cadeia", "imagem_url": null}, {"letra": "B", "texto": "reação física", "imagem_url": null}, {"letra": "C", "texto": "comburência", "imagem_url": null}, {"letra": "D", "texto": "ignição", "imagem_url": null}]'::jsonb, 'A', null),
('anac', '1615b1c0-8f80-46a2-b0d9-f510d061d4e2', 'Segurança e Emergência', null, 'NOS PROCEDIMENTOS EXECUTADOS PARA UM POUSO DE EMERGÊNCIA PREPARADO, LOGO APÓS O BRIEFING COM O COMANDANTE, O COMISSÁRIO DEVE', null, '[{"letra": "A", "texto": "FAZER O SPEECH DE POUSO DE EMERGÊNCIA", "imagem_url": null}, {"letra": "B", "texto": "RECOLHER OS OBJETOS SOLTOS NAS GALLEYS", "imagem_url": null}, {"letra": "C", "texto": "REDIRECIONAR OS PASSAGEIROS INCAPAZES E CRIANÇAS", "imagem_url": null}, {"letra": "D", "texto": "TRANSMITIR AOS DEMAIS COMISSÁRIOS, OS PROCEDIMENTOS ACORDADOS COM O COMANDANTE", "imagem_url": null}]'::jsonb, 'D', null),
('anac', 'f79ed501-c79d-4b04-ac9b-037dfe316a44', 'Segurança e Emergência', null, 'NUMA SOBREVIVÊNCIA, TENDO DECIDIDO ABANDONAR O ACAMPAMENTO E PROCURAR AJUDA CAMINHANDO PELA MATA, AO SE DEPARAR COM UM ACLIVE MUITO ACENTUADO À FRENTE, DEVE-SE, PREFERENCIALMENTE, CONTORNÁ-LO OU', null, '[{"letra": "A", "texto": "SUBIR EM LINHA RETA, POIS É O CAMINHO MAIS CURTO", "imagem_url": null}, {"letra": "B", "texto": "ESCALAR COM CORDAS OU OUTROS EQUIPAMENTOS DISPONÍVEIS", "imagem_url": null}, {"letra": "C", "texto": "PROCURAR ATRAVESSAR O OBSTÁCULO, SEM NENHUM CRITÉRIO", "imagem_url": null}, {"letra": "D", "texto": "SUBIR EM ZIGUEZAGUE, A FIM DE POUPAR AS ENERGIAS", "imagem_url": null}]'::jsonb, 'D', null),
('anac', 'd618bca1-dfb2-47da-9f38-e116245ad062', 'Segurança e Emergência', null, 'OS ÓRGÃOS DE CAÇA QUE POSSUEM VITAMINAS ESSENCIAIS, SÃO:', null, '[{"letra": "A", "texto": "pulmão, rins e miolo", "imagem_url": null}, {"letra": "B", "texto": "coração, rins e língua", "imagem_url": null}, {"letra": "C", "texto": "coração, estômago e miolo", "imagem_url": null}, {"letra": "D", "texto": "coração, fígado e rins", "imagem_url": null}]'::jsonb, 'D', null),
('anac', 'a3effe34-d6c0-4c34-adc3-bda02e800c6f', 'Segurança e Emergência', null, 'APÓS USAR UM EXTINTOR DE HALON OU DE PÓ QUÍMICO, PARA APAGAR FOGO EM POLTRONA, CORTINA, REVESTIMENTO OU PAPEL, DEVERÁ SER ADOTADO O PROCEDIMENTO DE:', null, '[{"letra": "A", "texto": "acionar a manutenção para que seja feita a limpeza necessária", "imagem_url": null}, {"letra": "B", "texto": "isolar a área afetada e avisar o comandante", "imagem_url": null}, {"letra": "C", "texto": "solicitar ao comandante que avalie a necessidade do uso de outro tipo de extintor", "imagem_url": null}, {"letra": "D", "texto": "rescaldar os resíduos, para que não haja reignição do fogo", "imagem_url": null}]'::jsonb, 'D', null),
('anac', '641e5ac4-2dc4-4bbb-885b-65cc1411c729', 'Segurança e Emergência', null, 'A ÁGUA DA CHUVA, QUANDO RETIRADA DO GRAVATÁ:', null, '[{"letra": "A", "texto": "poderá ser bebida, após 30 min", "imagem_url": null}, {"letra": "B", "texto": "deverá ser fervida por, pelo menos, 10 min", "imagem_url": null}, {"letra": "C", "texto": "poderá ser bebida imediatamente", "imagem_url": null}, {"letra": "D", "texto": "deve ser coada e purificada", "imagem_url": null}]'::jsonb, 'D', null),
('anac', 'cdd31e01-4da4-46b1-b12d-3abee4f3d91a', 'Segurança e Emergência', null, 'ANTES DO FECHAMENTO DE QUALQUER PORTA DA AERONAVE, O COMISSÁRIO DEVE TER O CUIDADO DE', null, '[{"letra": "A", "texto": "VERIFICAR A EXISTÊNCIA DE OBJETOS ESTRANHOS NO ENCAIXE DA MESMA", "imagem_url": null}, {"letra": "B", "texto": "AGUARDAR O AVISO DE PREPARAR PARA A PARTIDA", "imagem_url": null}, {"letra": "C", "texto": "FICAR AFASTADO DA MESMA", "imagem_url": null}, {"letra": "D", "texto": "OBSERVAR SE O AVISO LUMINOSO NÃO FUMAR ESTÁ DESLIGADO", "imagem_url": null}]'::jsonb, 'A', null),
('anac', '7ac6457e-3523-43fb-94a1-2a1e3fa602b1', 'Segurança e Emergência', null, 'OS PROCEDIMENTOS ADOTADOS PELO COMISSÁRIO DURANTE A DINÂMICA DE UMA EVACUAÇÃO DE EMERGÊNCIA POR EVIDÊNCIA SÃO, ABRIR OS(AS)', null, '[{"letra": "A", "texto": "SAÍDAS OPERATIVAS E CONDUZIR A EVACUAÇÃO DISCRETAMENTE", "imagem_url": null}, {"letra": "B", "texto": "CINTOS, VERIFICAR O COCKPIT E ABRIR AS SAÍDAS SOBRE AS ASAS", "imagem_url": null}, {"letra": "C", "texto": "CINTOS, ABRIR AS SAÍDAS OPERATIVAS E CONDUZIR A EVACUAÇÃO RÁPIDA E CADENCIADAMENTE", "imagem_url": null}, {"letra": "D", "texto": "SAÍDAS DO COCKPIT E DIRIGIR OS PASSAGEIROS PARA AS SAÍDAS DE EMERGÊNCIA", "imagem_url": null}]'::jsonb, 'C', null),
('anac', 'fc9fc586-c2dc-4736-a39d-179f257698d6', 'Segurança e Emergência', null, 'AS PORTAS DE UMA AERONAVE PODEM SER OPERADAS INTERNA E EXTERNAMENTE:', null, '[{"letra": "A", "texto": "somente em situação de emergência", "imagem_url": null}, {"letra": "B", "texto": "em situação normal e de emergência, com operação elétrica", "imagem_url": null}, {"letra": "C", "texto": "tanto em situação normal quanto em emergência", "imagem_url": null}, {"letra": "D", "texto": "apenas em situação normal", "imagem_url": null}]'::jsonb, 'C', null),
