('anac', '64dd3340-335f-4e69-b4e8-ea8f41e831b8', 'Segurança e Emergência', null, 'NO CASO DE DESIDRATAÇÃO DURANTE UMA SOBREVIVÊNCIA NO MAR, DEVE-SE:', null, '[{"letra": "A", "texto": "suspender a alimentação e os líquidos; fazer com que a pessoa descanse o máximo possível", "imagem_url": null}, {"letra": "B", "texto": "suspender a alimentação; dar bastante líquido, manter a pessoa em repouso", "imagem_url": null}, {"letra": "C", "texto": "dar bastante líquido e fazer com que a pessoa se distraia, dando-lhe funções diversas", "imagem_url": null}, {"letra": "D", "texto": "manter a roupa do sobrevivente sempre úmida para reidratá-lo, e manter a alimentação e líquido", "imagem_url": null}]'::jsonb, 'B', null),
