('anac', 'ff955a3c-ba9e-4b10-af6b-70aa7238d244', 'Segurança e Emergência', null, 'HAVENDO UMA EVACUAÇÃO COM UTILIZAÇÃO DE JANELAS DE EMERGÊNCIA SOBRE A ASA, TEM-SE COMO EQUIPAMENTO AUXILIAR DE EVACUAÇÃO TIRAS OU CORDA DE ESCAPE:', null, '[{"letra": "A", "texto": "que são embutidas ao encaixe superior da janela, ficando aparente somente com a retirada da janela", "imagem_url": null}, {"letra": "B", "texto": "que deverão ser usadas para amarrar os passageiros no extradorso da asa", "imagem_url": null}, {"letra": "C", "texto": "rápido, com utilização sem restrições em todos os pousos", "imagem_url": null}, {"letra": "D", "texto": "localizadas no extradorso da asa", "imagem_url": null}]'::jsonb, 'A', null),
