('anac', 'c3a10af5-fc1f-421a-83b1-3db69415315c', 'Segurança e Emergência', null, 'VISTAM O COLETE E SAIAM/TAKE YOUR LIFE VEST AND GET OUT, SÃO COMANDOS DE UMA EVACUAÇÃO', null, '[{"letra": "A", "texto": "EM POUSO NA ÁGUA", "imagem_url": null}, {"letra": "B", "texto": "EM POUSO NA SELVA", "imagem_url": null}, {"letra": "C", "texto": "PREPARADA", "imagem_url": null}, {"letra": "D", "texto": "EM POUSO FORÇADO", "imagem_url": null}]'::jsonb, 'A', null),
('anac', '1ac35d9f-0577-46cb-8a12-82217c699e2e', 'Segurança e Emergência', null, 'NUM POUSO DE EMERGÊNCIA EM TERRA AO CHECAR A OPERATIVIDADE DA SAÍDA DE EMERGÊNCIA DE SUA RESPONSABILIDADE O COMISSÁRIO VERIFICA QUE A MESMA ESTÁ EMPERRADA. O SEU PROCEDIMENTO A SEGUIR DEVERÁ SER:', null, '[{"letra": "A", "texto": "permanecer junto a saída e redirecionar os paxs para a mais próxima operativa", "imagem_url": null}, {"letra": "B", "texto": "segurar as alças da porta, para não ser retirado a força, e gritar para trás, porta emperrada", "imagem_url": null}, {"letra": "C", "texto": "ir até o cockpit e solicitar o comandante ou co-piloto ajudarem abrir a porta emperrada", "imagem_url": null}, {"letra": "D", "texto": "abandonar sua saída e ir ajudar um colega na saída operativa mais próxima", "imagem_url": null}]'::jsonb, 'D', null),
