('anac', '785bc9a9-5ae2-47aa-a2bf-075acdd1d7f5', 'Segurança e Emergência', null, 'COMO MEDIDA PREVENTIVA DE SEGURANÇA, HAVENDO QUALQUER TIPO DE ANORMALIDADE NA CABINE DE PASSAGEIROS, É DEVER DO COMISSÁRIO', null, '[{"letra": "A", "texto": "AVISAR, IMEDIATAMENTE, À TODA A TRIPULAÇÃO", "imagem_url": null}, {"letra": "B", "texto": "INFORMAR, APENAS, AO SUPERVISOR DE CABINE", "imagem_url": null}, {"letra": "C", "texto": "INFORMAR, SOMENTE, À EQUIPE DE COMISSÁRIOS", "imagem_url": null}, {"letra": "D", "texto": "RELATAR NO LIVRO DE BORDO", "imagem_url": null}]'::jsonb, 'A', null),
