('anac', '84abaf96-53fe-4738-b1d7-467500552766', 'Segurança e Emergência', null, 'O CUIDADO QUE SE DEVE TER COM A BIRUTA D''ÁGUA NO CASO DE UMA SOBREVIVÊNCIA NO MAR É:', null, '[{"letra": "A", "texto": "colocá-la de forma que seja possível coletar água da chuva", "imagem_url": null}, {"letra": "B", "texto": "logo que subir no bote, lançá-la para que os sobreviventes possam subir com maior facilidade", "imagem_url": null}, {"letra": "C", "texto": "armá-la logo que possível para destilar e dessalgar a água do mar", "imagem_url": null}, {"letra": "D", "texto": "verificar que não fique presa nos destroços da aeronave", "imagem_url": null}]'::jsonb, 'D', null),
