('anac', '1442cc81-6c51-4977-8d34-cedacc176973', 'Segurança e Emergência', null, 'NUNCA DEIXE DE PROVIDENCIAR EM SEU ACAMPAMENTO:', null, '[{"letra": "A", "texto": "fogueiras num raio de 50 e 100m", "imagem_url": null}, {"letra": "B", "texto": "soro antiofídico", "imagem_url": null}, {"letra": "C", "texto": "repelentes contra insetos", "imagem_url": null}, {"letra": "D", "texto": "comprimidos contra enjôo e calmantes", "imagem_url": null}]'::jsonb, 'A', null),
('anac', 'c19fb572-c621-4c37-bbc4-86e492fae4a3', 'Segurança e Emergência', null, 'COM EXCEÇÃO DO RÁDIO LOCALIZADOR, TODOS OS OUTROS SINALIZADORES ATIVOS DEVEM SER UTILIZADOS', null, '[{"letra": "A", "texto": "SEMPRE QUE FOR AVISTADA OU OUVIDA AERONAVE OU EMBARCAÇÃO", "imagem_url": null}, {"letra": "B", "texto": "DURANTE O DIA OU À NOITE", "imagem_url": null}, {"letra": "C", "texto": "ININTERRUPTAMENTE", "imagem_url": null}, {"letra": "D", "texto": "DE DIA, QUANDO NÃO HOUVER NUVENS E DE NOITE, QUANDO NÃO HOUVER OBSTÁCULOS À SINALIZAÇÃO", "imagem_url": null}]'::jsonb, 'A', null),
('anac', '693c7ed9-24b6-41a4-86a3-b1cdbb73d231', 'Segurança e Emergência', null, 'EM UMA SITUAÇÃO DE EMERGÊNCIA REAL, A INSTRUÇÃO QUE DEVERÁ SER DADA AOS PASSAGEIROS, EM RELAÇÃO À UTILIZAÇÃO DOS COLETES SALVA-VIDAS, ORIENTA PARA QUE ESTES SEJAM INFLADOS:', null, '[{"letra": "A", "texto": "quando os passageiros estiverem de pé no corredor", "imagem_url": null}, {"letra": "B", "texto": "após o pouso, dentro da aeronave", "imagem_url": null}, {"letra": "C", "texto": "com os passageiros sentados em seus lugares, antes do pouso", "imagem_url": null}, {"letra": "D", "texto": "na soleira da porta ou sobre a asa, antes de abandonar a aeronave", "imagem_url": null}]'::jsonb, 'D', null),
('anac', 'dc47ea34-738a-40f7-9dff-2252fc352f7b', 'Segurança e Emergência', null, 'EM COMBATE A FOGO A BORDO, DE PROVÁVEL ORIGEM ELÉTRICA, DEVE-SE, ENTRE OUTRAS MEDIDAS,', null, '[{"letra": "A", "texto": "ARMAR AS ESCORREGADEIRAS", "imagem_url": null}, {"letra": "B", "texto": "USAR MANTAS, JORNAIS E REVISTAS PARA ABAFAMENTO", "imagem_url": null}, {"letra": "C", "texto": "UMEDECER, ABUNDANTEMENTE, O LOCAL", "imagem_url": null}, {"letra": "D", "texto": "DESCONECTAR OS DISJUNTORES (CB´S) DA ÁREA AFETADA", "imagem_url": null}]'::jsonb, 'D', null),
('anac', 'a2917692-f569-404f-94fb-984a1ed96dce', 'Segurança e Emergência', null, 'INDIQUE O MOMENTO E O LOCAL EM QUE O USO DE CIGARROS É EXPRESSAMENTE PROIBIDO:', null, '[{"letra": "A", "texto": "somente nos toaletes e corredores da aeronave", "imagem_url": null}, {"letra": "B", "texto": "apenas nas áreas de não fumantes e durante as decolagens", "imagem_url": null}, {"letra": "C", "texto": "no solo, nos toaletes e durante os pousos ou turbulências", "imagem_url": null}, {"letra": "D", "texto": "em todas as fases do voo, no solo e nas escalas", "imagem_url": null}]'::jsonb, 'D', null),
('anac', '67b2baee-1a47-44de-9921-b4444d7c0707', 'Segurança e Emergência', null, 'APÓS O POUSO FORÇADO NA SELVA E CONSEQÜENTE EVACUAÇÃO DE EMERGÊNCIA, O MELHOR PROCEDIMENTO A SER ADOTADO PELOS SOBREVIVENTES SERÁ:', null, '[{"letra": "A", "texto": "permanecer perto da aeronave durante 24 horas, passado este prazo, deslocar os sobreviventes para perto de um rio", "imagem_url": null}, {"letra": "B", "texto": "usar a aeronave como abrigo para os feridos e metade do grupo, saindo a outra metade em busca de socorro", "imagem_url": null}, {"letra": "C", "texto": "se possível usar a aeronave como abrigo e esperar o salvamento", "imagem_url": null}, {"letra": "D", "texto": "procurar abrigo longe da aeronave e sair em busca de socorro", "imagem_url": null}]'::jsonb, 'C', null),
