('anac', '616d9c43-7b85-48f1-8ece-57812ffd2972', 'Segurança e Emergência', null, 'DE BRAÇOS ABERTOS, COM O BRAÇO DIREITO APONTANDO PARA O POENTE (OESTE), À SUA FRENTE ESTARÁ O', null, '[{"letra": "A", "texto": "NORTE", "imagem_url": null}, {"letra": "B", "texto": "LESTE", "imagem_url": null}, {"letra": "C", "texto": "SUL", "imagem_url": null}, {"letra": "D", "texto": "NORDESTE", "imagem_url": null}]'::jsonb, 'C', null),
('anac', '79fb1e0b-0d49-41b2-9ac8-e6792a20f4b2', 'Segurança e Emergência', null, 'A MACHADINHA DE BORDO É COMPOSTA DE UM CABO ISOLANTE E', null, '[{"letra": "A", "texto": "UM LADO CORTANTE E OUTRO PERFURANTE", "imagem_url": null}, {"letra": "B", "texto": "UM LADO CORTANTE E OUTRO ISOLANTE", "imagem_url": null}, {"letra": "C", "texto": "DOIS LADOS PERFURANTES", "imagem_url": null}, {"letra": "D", "texto": "DOIS LADOS CORTANTES", "imagem_url": null}]'::jsonb, 'A', null),
('anac', '85f79ce2-496d-4c5f-9356-7299d39e2e71', 'Segurança e Emergência', null, 'CONDUÇÃO É A FORMA DE TRANSMISSÃO DE CALOR QUE OCORRE:', null, '[{"letra": "A", "texto": "por meio de ondas através do espaço ou materiais", "imagem_url": null}, {"letra": "B", "texto": "através da proximidade de uma molécula a outra molécula do material combustível", "imagem_url": null}, {"letra": "C", "texto": "por meio de deslocamento de uma massa de ar aquecida", "imagem_url": null}, {"letra": "D", "texto": "de forma gradual e lenta, deslocando-se pelos espaços vazios", "imagem_url": null}]'::jsonb, 'B', null),
