('anac', '3cbf6e73-2925-4c55-83e5-9892b6829baf', 'Segurança e Emergência', null, 'QUALQUER PASSAGEIRO QUE ESTIVER RECEBENDO OXIGÊNIO TERAPÊUTICO POR TEMPO PROLONGADO, SOFRERÁ UM RESSECA MENTO NO ROSTO E NAS MUCOSAS. PARA MINIMIZAR OS EFEITOS DESTE RESSECA MENTO, DEVE-SE:', null, '[{"letra": "A", "texto": "promover a cada dez minutos a umidificação da área verificando a necessidade de continuar a aplicação de oxigênio", "imagem_url": null}, {"letra": "B", "texto": "dar um copo de água a cada dez minutos para umidificação da área verificando a necessidade de continuar a aplicação de oxigênio", "imagem_url": null}, {"letra": "C", "texto": "ministrar oxigênio apenas por vinte minutos e solicitar orientação de um médico a bordo", "imagem_url": null}, {"letra": "D", "texto": "aplicar qualquer substância gordurosa no rosto", "imagem_url": null}]'::jsonb, 'A', null),
