('anac', 'b3d1ca5f-4d9e-4a03-8480-123fe1057aaa', 'Segurança e Emergência', null, 'OS CINTOS DE SEGURANÇA DOS TRIPULANTES SÃO DO TIPO TÓRACO-ABDOMINAL. TAL CARACTERÍSTICA PERMITE QUE OS TRIPULANTES', null, '[{"letra": "A", "texto": "TENHAM MAIOR CONFORTO", "imagem_url": null}, {"letra": "B", "texto": "MANTENHAM ERETAS SUAS COLUNAS", "imagem_url": null}, {"letra": "C", "texto": "FAÇAM SUAS REFEIÇÕES, MAIS APROPRIADAMENTE ACOMODADOS", "imagem_url": null}, {"letra": "D", "texto": "FIQUEM MAIS SEGUROS, ENQUANTO ESTIVEREM SENTADOS", "imagem_url": null}]'::jsonb, 'D', null),
