('anac', '90c23ef1-e6d1-4e6c-8ec2-27634ad7fdcc', 'Segurança e Emergência', null, 'USEM AQUELA SAÍDA/USE THAT WAY OU SIMILARES, SÃO COMANDOS DE EVACUAÇÃO UTILIZADOS EM CASO DE', null, '[{"letra": "A", "texto": "PORTA INOPERANTE OU ÁREA EXTERNA IMPEDIDA", "imagem_url": null}, {"letra": "B", "texto": "POUSO NA SELVA, COM FOGO NAS TURBINAS", "imagem_url": null}, {"letra": "C", "texto": "POUSO EM ÁGUAS TURVAS", "imagem_url": null}, {"letra": "D", "texto": "POUSO COM PANE NO SISTEMA DE INTERFONES", "imagem_url": null}]'::jsonb, 'A', null),
('anac', '45c2870e-d027-4744-8a26-1d2583c09065', 'Segurança e Emergência', null, 'NA CAÇA, EM UMA SOBREVIVÊNCIA NA SELVA, PODERÃO SER UTILIZADAS ARMADILHAS DO TIPO:', null, '[{"letra": "A", "texto": "jacus e tarimbas", "imagem_url": null}, {"letra": "B", "texto": "zagaias e cipós", "imagem_url": null}, {"letra": "C", "texto": "arapucas e laços", "imagem_url": null}, {"letra": "D", "texto": "anzóis e aratacas", "imagem_url": null}]'::jsonb, 'C', null),
