('anac', '511f1dad-72ab-42af-8d15-a83c4d52faae', 'Segurança e Emergência', null, 'O SERVIÇO DE BUSCA E SALVAMENTO É CONHECIDO MUNDIALMENTE PELA SIGLA:', null, '[{"letra": "A", "texto": "SBS", "imagem_url": null}, {"letra": "B", "texto": "ATS", "imagem_url": null}, {"letra": "C", "texto": "SAR", "imagem_url": null}, {"letra": "D", "texto": "TWR", "imagem_url": null}]'::jsonb, 'C', null),
('anac', 'a4b4e01f-2894-43ec-8557-4d03056e58a2', 'Segurança e Emergência', null, 'DE FRENTE PARA UMA FOGUEIRA, O CALOR CHEGA ATÉ O SOBREVIVENTE POR:', null, '[{"letra": "A", "texto": "convecção", "imagem_url": null}, {"letra": "B", "texto": "condução", "imagem_url": null}, {"letra": "C", "texto": "irradiação", "imagem_url": null}, {"letra": "D", "texto": "advecção", "imagem_url": null}]'::jsonb, 'C', null),
('anac', '56666e98-c127-4723-89bd-190af4ee11e3', 'Segurança e Emergência', null, 'AS ARMADILHAS E ALÇAPÕES PARA PÁSSAROS E PEQUENOS ANIMAIS DEVERÃO SER ARMADOS', null, '[{"letra": "A", "texto": "PELA MANHÃ E VERIFICADOS À TARDE", "imagem_url": null}, {"letra": "B", "texto": "DURANTE O PÔR-DO-SOL, APENAS", "imagem_url": null}, {"letra": "C", "texto": "AO ANOITECER E VERIFICADOS PELA MANHÃ BEM CEDO", "imagem_url": null}, {"letra": "D", "texto": "DURANTE A AURORA, SOMENTE", "imagem_url": null}]'::jsonb, 'C', null),
('anac', 'a1bc63fa-1a8a-4b5c-8b4f-43d5f0790216', 'Segurança e Emergência', null, 'PARA CASOS DE VOOS DE EMERGÊNCIA NO MAR, AS AERONAVES QUE OPERAM VOOS TRANSOCEÂNICOS TEM OBRIGATORIEDADE DE PORTAR EQUIPAMENTOS DE FLUTUAÇÃO INDIVIDUAIS E COLETIVOS. IDENTIFIQUE-OS ABAIXO:', null, '[{"letra": "A", "texto": "barcos salva-vidas e escorregadeiras simples", "imagem_url": null}, {"letra": "B", "texto": "escorregadeiras simples e assentos flutuantes", "imagem_url": null}, {"letra": "C", "texto": "assentos flutuantes e coletes salva-vidas", "imagem_url": null}, {"letra": "D", "texto": "coletas salva-vidas e barcos salva-vidas", "imagem_url": null}]'::jsonb, 'D', null),
('anac', '3c115123-8e6d-4c7c-81e2-9bfd3c3cfe9e', 'Segurança e Emergência', null, 'AO SE MONTAR UMA FOGUEIRA, PARA SE CONSEGUIR O MÁXIMO DE CALOR E PROTEÇÃO DO FOGO, DEVE-SE ARMÁ-LA', null, '[{"letra": "A", "texto": "NO MEIO DE ARBUSTOS PARA QUE O VENTO NÃO A APAGUE", "imagem_url": null}, {"letra": "B", "texto": "PRÓXIMO A UMA ROCHA OU A UM MURO FEITO DE TRONCOS", "imagem_url": null}, {"letra": "C", "texto": "JUNTO AOS DESTROÇOS DA AERONAVE, PARA SE APROVEITAR O SEU COMBUSTÍVEL", "imagem_url": null}, {"letra": "D", "texto": "NO MEIO DO ACAMPAMENTO, POIS AS PESSOAS SERVIRÃO DE PROTEÇÃO", "imagem_url": null}]'::jsonb, 'B', null),
('anac', '983b78c0-7a20-4ab2-901e-c300cd6c9993', 'Segurança e Emergência', null, 'COM RELAÇÃO AO ASSUNTO DESCRITO A SEGUIR, IDENTIFIQUE A ALTERNATIVA MAIS CORRETA. EM SITUAÇÃO NORMAL, DURANTE AS OPERAÇÕES DE DECOLAGEM E POUSO, OS COMISSÁRIOS, POR MEDIDA DE SEGURANÇA, DEVEM:', null, '[{"letra": "A", "texto": "checar apenas a posição das poltronas e a colocação de cintos de segurança", "imagem_url": null}, {"letra": "B", "texto": "alertar os passageiros para que observem somente, os avisos luminosos", "imagem_url": null}, {"letra": "C", "texto": "verificar a área externa da aeronave", "imagem_url": null}, {"letra": "D", "texto": "executar com rigor os cheques preparatórios com relação a passageiros, cabines, galleys e toaletes", "imagem_url": null}]'::jsonb, 'D', null),
('anac', '4201d587-4614-402d-90a7-7e7002aa2431', 'Segurança e Emergência', null, 'UMA COBRA PICOU UM CRIANÇA E FUGIU. NO LOCAL DA PICADA, HÁ LINHAS DE ESCORIAÇÕES SANGRENTAS, SEM ORIFÍCIOS NÍTIDOS, TRATA-SE DE PICADA DE COBRA:', null, '[{"letra": "A", "texto": "urutu", "imagem_url": null}, {"letra": "B", "texto": "coral venenosa", "imagem_url": null}, {"letra": "C", "texto": "jararaca", "imagem_url": null}, {"letra": "D", "texto": "jibóia", "imagem_url": null}]'::jsonb, 'D', null),
('anac', 'dfb95224-9a72-445e-9729-8f4c20ca8bf4', 'Segurança e Emergência', null, 'LEVANDO-SE EM CONTA A ROSA DOS VENTOS, ESTANDO-SE O BRAÇO DIREITO NA DIREÇÃO QUE O SOL NASCE, TEM-SE QUE O:', null, '[{"letra": "A", "texto": "Oeste fica na direção do braço direito", "imagem_url": null}, {"letra": "B", "texto": "Sul fica na direção do rosto", "imagem_url": null}, {"letra": "C", "texto": "Norte fica na direção do rosto", "imagem_url": null}, {"letra": "D", "texto": "Leste fica na direção do braço esquerdo", "imagem_url": null}]'::jsonb, 'C', null),
('anac', 'd4566293-d77b-4af3-b0b5-5957245c0ad7', 'Segurança e Emergência', null, 'NUM POUSO DE EMERGÊNCIA PREPARADO, ENQUANTO UM DOS COMISSÁRIOS FAZ O ANÚNCIO ESPECÍFICO, OS DEMAIS DISTRIBUEM-SE AO LONGO DA CABINE PARA', null, '[{"letra": "A", "texto": "CHAMAR A ATENÇÃO PARA O ANÚNCIO E CONTER O PÂNICO", "imagem_url": null}, {"letra": "B", "texto": "REALOCAR OS PASSAGEIROS CONSIDERADOS INCAPAZES", "imagem_url": null}, {"letra": "C", "texto": "VERIFICAR A ABERTURA DAS PORTAS E JANELAS EM EMERGÊNCIA", "imagem_url": null}, {"letra": "D", "texto": "EXPLICAR DETALHES DO PROCEDIMENTO", "imagem_url": null}]'::jsonb, 'A', null),
('anac', '76f387e7-c819-483e-a374-05f1cdce35ff', 'Segurança e Emergência', null, 'NAS AERONAVES, EM GERAL, HAVENDO FALHA NO SISTEMA PRINCIPAL DE ILUMINAÇÃO,', null, '[{"letra": "A", "texto": "AS LUZES DE EMERGÊNCIA SE ACENDERÃO AUTOMATICAMENTE", "imagem_url": null}, {"letra": "B", "texto": "AUTOMATICAMENTE, OS FARÓIS DA AERONAVE SERÃO ACESOS", "imagem_url": null}, {"letra": "C", "texto": "UM SISTEMA SECUNDÁRIO SERÁ ACIONADO", "imagem_url": null}, {"letra": "D", "texto": "IMEDIATAMENTE AS LUZES DE LEITURA SERÃO ACESAS", "imagem_url": null}]'::jsonb, 'A', null),
('anac', 'bfae728a-8544-44e9-bafc-fee4c6651315', 'Segurança e Emergência', null, 'INDIQUE OS EQUIPAMENTOS QUE O COMISSÁRIO DEVE USAR PARA COMBATER, DIRETAMENTE, UM INCÊNDIO A BORDO.', null, '[{"letra": "A", "texto": "COLETE SALVA-VIDAS, ROUPA DE AMIANTO, MÁSCARA CONTRA GASES", "imagem_url": null}, {"letra": "B", "texto": "EXTINTOR ADEQUADO, LUVAS DE KEVLAR E CAPUZ ANTI-FUMAÇA", "imagem_url": null}, {"letra": "C", "texto": "MÁSCARA CONTRA GASES, EXTINTOR DE PÓ QUÍMICO E COLETE SALVA-VIDAS", "imagem_url": null}, {"letra": "D", "texto": "COLETE PROTETOR, ROUPA REFLEXIVA E EXTINTOR ADEQUADO", "imagem_url": null}]'::jsonb, 'B', null),
('anac', 'bc6cd6ac-4bb2-4de2-9eec-e1e31288b943', 'Segurança e Emergência', null, 'PARA ABRIR UMA SAÍDA DE EMERGÊNCIA SOBRE A ASA, PELO LADO DE FORA, DEVE-SE:', null, '[{"letra": "A", "texto": "puxar o comando superior da janela para baixo", "imagem_url": null}, {"letra": "B", "texto": "puxar o comando inferior para baixo", "imagem_url": null}, {"letra": "C", "texto": "pressionar o retângulo acima do visor da janela para dentro", "imagem_url": null}, {"letra": "D", "texto": "NDA", "imagem_url": null}]'::jsonb, 'C', null),
