('anac', 'da7f150f-021f-4d3c-bed8-b3a18f5b4b87', 'Segurança e Emergência', null, 'DESCONTINUADA...NA SINALIZAÇÃO VISUAL TERRA E AR, A LETRA F SIGNIFICA:', null, '[{"letra": "A", "texto": "necessitamos alimento e água", "imagem_url": null}, {"letra": "B", "texto": "não podemos prosseguir viagem", "imagem_url": null}, {"letra": "C", "texto": "indique o que os sobreviventes devem fazer", "imagem_url": null}, {"letra": "D", "texto": "provavelmente pode-se pousar aqui com  segurança", "imagem_url": null}]'::jsonb, 'A', null),
('anac', 'eabf188f-c0a5-4cf4-8ec3-a9b8639e98b8', 'Segurança e Emergência', null, 'SE DURANTE UMA EVACUAÇÃO, AO OLHAR PELO VISOR DA SAÍDA DE EMERGÊNCIA, O COMISSÁRIO PERCEBER FOGO NA ÁREA EXTERNA, DEVERÁ ADOTAR O SEGUINTE PROCEDIMENTO:', null, '[{"letra": "A", "texto": "ABRIR A PORTA E COMANDAR A EVACUAÇÃO COM RAPIDEZ E RITMO", "imagem_url": null}, {"letra": "B", "texto": "MANTER A PORTA FECHADA E PERMANECER JUNTO À MESMA, REDIRECIONANDO OS PASSAGEIROS PARA AS SAÍDAS OPERANTES", "imagem_url": null}, {"letra": "C", "texto": "MANTER A PORTA FECHADA E AGUARDAR A CHEGADA DOS BOMBEIROS PARA, DEPOIS, COMANDAR A EVACUAÇÃO", "imagem_url": null}, {"letra": "D", "texto": "ABRIR A PORTA E TENTAR EXTINGUIR O FOCO DE INCÊNDIO COMO OS EQUIPAMENTOS DE BORDO", "imagem_url": null}]'::jsonb, 'B', null),
