('anac', '86585c1a-282a-482d-ba28-19a6f615bba0', 'Segurança e Emergência', null, 'DE ACORDO COM OS CUIDADOS GERAIS A SEREM OBSERVADOS EM CASO DE SOBREVIVÊNCIA, DEVEMOS', null, '[{"letra": "A", "texto": "DORMIR DE FORMA FRAGMENTADA EM FUNÇÃO DA VIGÍLIA", "imagem_url": null}, {"letra": "B", "texto": "ACIMA DE TUDO, PROVIDENCIAR ALIMENTOS DE ORIGEM ANIMAL", "imagem_url": null}, {"letra": "C", "texto": "MANTER A CALMA, NÃO NOS APRESSAR E PRESERVAR O SONO", "imagem_url": null}, {"letra": "D", "texto": "MANTER TURNOS DE CAÇA CONSTANTES E FAZER EXERCÍCIOS REGULARES", "imagem_url": null}]'::jsonb, 'C', null),
('anac', '9210dab4-5268-4c39-8c68-9f4dde208124', 'Segurança e Emergência', null, 'O GARROTEAMENTO OU TORNIQUETE, NO CASO DE PICADA DE COBRAS DO GRUPO BOTHROPS, PODERÁ:', null, '[{"letra": "A", "texto": "cessar a ação de veneno", "imagem_url": null}, {"letra": "B", "texto": "gangrenar o local afetado", "imagem_url": null}, {"letra": "C", "texto": "salvar a vítima impedindo que o veneno se espalhe", "imagem_url": null}, {"letra": "D", "texto": "diminuir a ação da dor", "imagem_url": null}]'::jsonb, 'B', null),
('anac', 'ba0d0e27-9564-47ff-9ec9-0760bf716711', 'Segurança e Emergência', null, 'TENDO DE PERMANECER 6 DIAS NA SELVA, APÓS UM POUSO DE EMERGÊNCIA, DEVEMOS DISTRIBUIR AS PROVISÕES:', null, '[{"letra": "A", "texto": "distribui-se toda a ração de alimento para o 1º dia", "imagem_url": null}, {"letra": "B", "texto": "1/2 para os 3 primeiros dias e 1/2 para os outros 3 dias", "imagem_url": null}, {"letra": "C", "texto": "2/3 para os 3 primeiros dias e 1/3 para os outros 3 dias", "imagem_url": null}, {"letra": "D", "texto": "1/3 para os 3 primeiros dias e 2/3 para os outros 3 dias", "imagem_url": null}]'::jsonb, 'C', null),
