('anac', 'cb0b6fd1-b51b-4dbc-b8e7-1305ecfdce68', 'Segurança e Emergência', null, 'APÓS A ABERTURA DAS PORTAS EM EMERGÊNCIA, COM AS ESCORREGADEIRAS INFLADAS E PRONTAS PARA USO, USAM-SE OS COMANDOS', null, '[{"letra": "A", "texto": "POR AQUI, POR AQUI/ THIS WAY, THIS WAY", "imagem_url": null}, {"letra": "B", "texto": "PEGUEM SEUS COLETES/TAKE YOUR VESTS", "imagem_url": null}, {"letra": "C", "texto": "ABAIXEM-SE, ABAIXEM-SE/ BRACE, BRACE", "imagem_url": null}, {"letra": "D", "texto": "SAIAM POR AQUELA PORTA/USE THAT DOOR", "imagem_url": null}]'::jsonb, 'A', null),
