('anac', '8fc680a2-935a-48b7-884c-b7a5d6ef9f72', 'Segurança e Emergência', null, 'EM CASO DE INCÊNDIO A BORDO, HAVENDO FUMAÇA DENSA NA CABINE, A MELHOR MANEIRA DE SE DESLOCAR RUMO À SAÍDA DE EMERGÊNCIA É', null, '[{"letra": "A", "texto": "ANDAR NORMALMENTE, POIS NAS PARTES MAIS ALTAS EXISTE MAIS OXIGÊNIO", "imagem_url": null}, {"letra": "B", "texto": "ANDAR DE CÓCORAS, POIS NAS PARTES MENOS ALTAS EXISTE MAIS OXIGÊNIO", "imagem_url": null}, {"letra": "C", "texto": "ANDAR AGACHADO PELO CHÃO, PROTEGENDO OS OLHOS E O NARIZ", "imagem_url": null}, {"letra": "D", "texto": "ARRASTAR-SE PELO CHÃO, POIS NESTE NÍVEL O AR É MENOS CONTAMINADO", "imagem_url": null}]'::jsonb, 'D', null),
