('anac', '34f486f3-6f8e-4f6c-8685-f6d19bd69a26', 'Segurança e Emergência', null, 'DENTRE AS ALTERNATIVAS ABAIXO, INDIQUE A MAIS CORRETA, COM RELAÇÃO AO QUE É ACONSELHÁVEL SER UTILIZADO POR SOBREVIVENTES QUE ESTEJAM EM UM BOTE NO MAR:', null, '[{"letra": "A", "texto": "óleo bronzeador, óculos escuros e pouca roupa", "imagem_url": null}, {"letra": "B", "texto": "toldo de proteção lateral, dossel de cobertura e vestimenta que cubra todo o corpo", "imagem_url": null}, {"letra": "C", "texto": "somente chapéu, óculos e protetor contra queimaduras", "imagem_url": null}, {"letra": "D", "texto": "apenas um dossel de cobertura que também serve para captura de água", "imagem_url": null}]'::jsonb, 'B', null),
('anac', 'ebc70ec0-ef60-4192-a892-338f966fc407', 'Segurança e Emergência', null, 'INDIQUE A SEQUÊNCIA CORRETA DE ABERTURA EXTERNA DA JANELA DO LADO DIREITO DO COCKPIT.', null, '[{"letra": "A", "texto": "PRESSIONAR O RETÂNGULO VERMELHO (PUSH); MOVER A JANELA EM DIREÇÃO À CAUDA DO AVIÃO ATÉ O SEU TRAVAMENTO", "imagem_url": null}, {"letra": "B", "texto": "PRESIONAR O CÍRCULO VERDE (PUSH); AGUARDAR O MOVIMENTO PNEUMÁTICO DA JANELA", "imagem_url": null}, {"letra": "C", "texto": "PUXAR O LOSANGO AZUL (PULL); MOVER A JANELA EM DIREÇÃO AO NARIZ DO AVIÃO, INDEFINIDAMENTE", "imagem_url": null}, {"letra": "D", "texto": "PUXAR O TRIÂNGULO AMARELO (PULL); RETIRAR O BATENTE DA JANELA DA FUSELAGEM E ABRI-LA", "imagem_url": null}]'::jsonb, 'A', null),
('anac', '05a88852-306b-4e14-a37f-c309b3638815', 'Segurança e Emergência', null, 'OS SOROS ESPECÍFICOS PARA PICADA DE CASCAVEL E DE URUTU SÃO RESPECTIVAMENTE, SORO ANTI:', null, '[{"letra": "A", "texto": "crotálico e botrópico", "imagem_url": null}, {"letra": "B", "texto": "laquético e crotálico", "imagem_url": null}, {"letra": "C", "texto": "botrópico e crotálico", "imagem_url": null}, {"letra": "D", "texto": "laquético e botrópico", "imagem_url": null}]'::jsonb, 'A', null),
('anac', '856d636d-821b-4062-8125-153157004382', 'Segurança e Emergência', null, 'UM PROCEDIMENTO DE SEGURANÇA ADOTADO PELOS COMISSÁRIOS EM VOOS NOTURNOS É DURANTE OS POUSOS E DECOLAGENS:', null, '[{"letra": "A", "texto": "manter a lanterna elétrica de mão acesa, discretamente e sem que os passageiros percebam", "imagem_url": null}, {"letra": "B", "texto": "deixar todas as luzes acesas para que os paxs possam acompanhar as decolagens e os pousos", "imagem_url": null}, {"letra": "C", "texto": "manter o vídeo ligado para que os paxs se distraiam e não fiquem preocupados com a operação da aeronave", "imagem_url": null}, {"letra": "D", "texto": "aumentar o volume da música, após a locução preparação para o pouso para distrair os paxs", "imagem_url": null}]'::jsonb, 'A', null),
