('anac', '4a7ad2f1-63aa-4e8b-872b-58c09a587b5e', 'Segurança e Emergência', null, 'O MOMENTO ADEQUADO PARA SE ABRIR AS SAÍDAS DE EMERGÊNCIA, QUANTO UMA EVACUAÇÃO SE TORNAR EVIDENTE, APÓS A PARADA TOTAL DA AERONAVE, SERÁ:', null, '[{"letra": "A", "texto": "aguardar a chegada do serviço de apoio terrestre", "imagem_url": null}, {"letra": "B", "texto": "combater o fogo, se houver, porque há risco de explosão", "imagem_url": null}, {"letra": "C", "texto": "aguardar a chegada do corpo de bombeiros e da manutenção do aeroporto", "imagem_url": null}, {"letra": "D", "texto": "efetuar o corte dos motores e verificação da área externa", "imagem_url": null}]'::jsonb, 'D', null),
('anac', 'b4e54f1b-9e10-4ba3-af22-d0fc5cc6eca8', 'Segurança e Emergência', null, 'HAVENDO UM CURTO-CIRCUITO EM LÂMPADAS, FIOS OU INTERRUPTORES, COM PRINCÍPIO DE INCÊNDIO, DEVE-SE', null, '[{"letra": "A", "texto": "DESLIGAR A CORRENTE ELÉTRICA DO LOCAL E EXTINGUIR O FOGO COM O EXTINTOR ADEQUADO", "imagem_url": null}, {"letra": "B", "texto": "UTILIZAR EXTINTOR DE HALON E FAZER O RESCALDO, SOMENTE", "imagem_url": null}, {"letra": "C", "texto": "JOGAR SOBRE O FOGO ÁGUA OU QUALQUER LÍQUIDO DISPONÍVEL", "imagem_url": null}, {"letra": "D", "texto": "PRIMEIRO, COMBATER O FOGO COM O EXTINTOR APROPRIADO E, DEPOIS, DESLIGAR A CORRENTE, ANTES DO RESCALDO", "imagem_url": null}]'::jsonb, 'A', null),
