('anac', '75b47936-9942-425e-a5a2-0a85d5294f80', 'Segurança e Emergência', null, 'QUANDO NO COMBATE A INCÊNDIO DE EQUIPAMENTOS ELÉTRICOS ENERGIZADOS SE CORTA A FONTE DE ENERGIA COM O OBJETIVO DE:', null, '[{"letra": "A", "texto": "obter uma maior eficácia no combate uma vez que o combatente poderá fazer uso dos extintores de forma correta", "imagem_url": null}, {"letra": "B", "texto": "transformar em incêndio classe C em A e ter-se mais opções de combate ao fogo", "imagem_url": null}, {"letra": "C", "texto": "possibilitar ao combatente utiliza os extintores que tem por princípio de extinção o abafamento", "imagem_url": null}, {"letra": "D", "texto": "facilitar o acesso ao local onde está ocorrendo o fogo para o combate", "imagem_url": null}]'::jsonb, 'B', null),
