('anac', '54a8de4d-0e4a-4166-b44b-b92b146ed0cb', 'Segurança e Emergência', null, 'OS COLETES SALVA-VIDA EM CRIANÇAS DEVERÁ SER AJUSTADO:', null, '[{"letra": "A", "texto": "nos ombros e na cintura entre as pernas", "imagem_url": null}, {"letra": "B", "texto": "na cintura e entre as pernas", "imagem_url": null}, {"letra": "C", "texto": "na cintura e nos ombros", "imagem_url": null}, {"letra": "D", "texto": "nos ombros e nas pernas", "imagem_url": null}]'::jsonb, 'A', null),
('anac', '7f402fff-ec22-46db-af25-6b7c954838e6', 'Segurança e Emergência', null, 'VISANDO A SEGURANÇA DOS PASSAGEIROS, AO SEREM COMUNICADOS QUE PASSARÃO POR TURBULÊNCIA, OS COMISSÁRIOS ADOTAM ALGUNS PROCEDIMENTOS:', null, '[{"letra": "A", "texto": "guardar as bagagens de mão nos toaletes e suspendem os serviços de bordo", "imagem_url": null}, {"letra": "B", "texto": "orientam os passageiros para que atem os cintos de segurança e reclinem a cadeira", "imagem_url": null}, {"letra": "C", "texto": "suspendem o serviço de bordo, travam os compartimentos da galley e avisam aos passageiros", "imagem_url": null}, {"letra": "D", "texto": "travam os compartimentos da  galley, verificam se todas as portas de emergência estão fechadas e os cintos de segurança atados", "imagem_url": null}]'::jsonb, 'C', null),
('anac', '042bbda9-a622-4d7c-b137-888652ec6515', 'Segurança e Emergência', null, 'O OXIGÊNIO TERAPÊUTICO TEM COMO FINALIDADE', null, '[{"letra": "A", "texto": "ATENDER PASSAGEIROS E TRIPULANTES EM CASO DE DESPRESSURIZAÇÃO", "imagem_url": null}, {"letra": "B", "texto": "ATENDER PASSAGEIROS QUE ESTEJAM COM PARADA CIRCULATÓRIA", "imagem_url": null}, {"letra": "C", "texto": "ATENDER PASSAGEIROS E TRIPULANTES COM INSUFICIÊNCIA RESPIRATÓRIA", "imagem_url": null}, {"letra": "D", "texto": "SERVIR DE PROTEÇÃO NO COMBATE AO FOGO", "imagem_url": null}]'::jsonb, 'C', null),
