('anac', 'baa91b77-1b43-4bfe-b4c9-66f737860c5c', 'Segurança e Emergência', null, 'ASSINALE A ALTERNATIVA EM QUE O USO DO EXTINTOR DE ÁGUA É O MAIS INDICADO.', null, '[{"letra": "A", "texto": "FOGO NO FORNO ENERGIZADO DA GALLEY", "imagem_url": null}, {"letra": "B", "texto": "FOGO EM UMA DAS POLTRONAS DOS PASSAGEIROS", "imagem_url": null}, {"letra": "C", "texto": "FOGO NO RESERVATÓRIO DE FLUÍDO HIDRÁULICO", "imagem_url": null}, {"letra": "D", "texto": "FOGO NO PAINEL DA CABINE DE COMANDO", "imagem_url": null}]'::jsonb, 'B', null),
('anac', '9d7d8421-3418-4ed8-99a0-69716be82fe0', 'Segurança e Emergência', null, 'O MATERIAL A SER UTILIZADO PARA FAZER FUMAÇA BRANCA, DURANTE UMA SOBREVIVÊNCIA NA SELVA É:', null, '[{"letra": "A", "texto": "panos, grande quantidade de água, qualquer tipo de folhas", "imagem_url": null}, {"letra": "B", "texto": "folhas verdes, musgos e pequena quantidade de água", "imagem_url": null}, {"letra": "C", "texto": "folhas secas, musgos e pequena quantidade de água", "imagem_url": null}, {"letra": "D", "texto": "borracha, óleo, plástico ou qualquer outro derivado do petróleo", "imagem_url": null}]'::jsonb, 'B', null),
('anac', 'ea6dca19-3b4a-461b-b8e3-e7c765af7a7f', 'Segurança e Emergência', null, 'COMBUSTÃO ATIVA É AQUELA:', null, '[{"letra": "A", "texto": "que atinge altas temperaturas rapidamente, caracterizando-se por violenta dilatação de gases e, que exercem pressão às paredes que os confiam", "imagem_url": null}, {"letra": "B", "texto": "em que os materiais armazenados fermentam gradativamente e, ao elevar-se a temperatura, faz o  combustível atingir o seu ponto de ignição", "imagem_url": null}, {"letra": "C", "texto": "em que o fogo só produz calor, não apresenta chama, porque o ambiente é rico em oxigênio", "imagem_url": null}, {"letra": "D", "texto": "em que o fogo, além de produzir calor, produz chama, porque o ambiente é rico em oxigênio", "imagem_url": null}]'::jsonb, 'D', null),
('anac', '14cac66b-6d35-4b84-bd1d-011b5f072ea9', 'Segurança e Emergência', null, 'DURANTE O RESCALDO EFETUADO APÓS EXTINÇÃO DE FOCO DE INCÊNDIO, VISANDO REVOLVER O MATERIAL QUE QUEIMOU EM PROFUNDIDADE, DEVE-SE USAR, PREFERENCIALMENTE, UM (A)', null, '[{"letra": "A", "texto": "MACHADINHA", "imagem_url": null}, {"letra": "B", "texto": "CILINDRO DE OXIGÊNIO", "imagem_url": null}, {"letra": "C", "texto": "EXTINTOR UTILIZADO", "imagem_url": null}, {"letra": "D", "texto": "GARRAFA PLÁSTICA VAZIA", "imagem_url": null}]'::jsonb, 'A', null),
('anac', '10782461-784a-4f92-9c73-3b6af6cb3cbc', 'Segurança e Emergência', null, 'DEVE-SE USAR O CORANTE DE MARCAÇÃO:', null, '[{"letra": "A", "texto": "junto com o repelente de tubarão - é mais eficaz", "imagem_url": null}, {"letra": "B", "texto": "ao se ouvir uma aeronave/navio, durante o dia", "imagem_url": null}, {"letra": "C", "texto": "ao se ouvir uma aeronave/navio, durante a noite", "imagem_url": null}, {"letra": "D", "texto": "nunca junto com o repelente, sempre que se ouvir/vir uma aeronave/navio", "imagem_url": null}]'::jsonb, 'B', null),
