('anac', 'b7e1b1be-25b6-44f3-b674-d99041cddf43', 'Segurança e Emergência', null, 'NUM INCÊNDIO A BORDO, EM QUE HAJA FUMAÇA NA CABINE, A MELHOR MANEIRA DE SE DESLOCAR RUMO À SAÍDA DE EMERGÊNCIA É', null, '[{"letra": "A", "texto": "ARRASTAR-SE PELO CHÃO, POIS A TEMPERATURA É MENOR", "imagem_url": null}, {"letra": "B", "texto": "ANDAR EM FILA INDIANA, PROTEGENDO OLHOS E NARIZ", "imagem_url": null}, {"letra": "C", "texto": "ANDAR NORMALMENTE, POIS NAS PARTES ALTAS EXISTE AR MENOS CONTAMINADO", "imagem_url": null}, {"letra": "D", "texto": "ARRASTAR-SE PELO CHÃO, MANTENDO A CABEÇA ERGUIDA E IMPROVISAR FILTROS, POIS JUNTO AO SOLO HÁ MENOS FUMAÇA", "imagem_url": null}]'::jsonb, 'D', null),
