('anac', '734d782e-de30-4f20-aefe-10f6f307b203', 'Segurança e Emergência', null, 'PARA QUE AS LUZES DE EMERGÊNCIA POSSAM FUNCIONAR AUTOMATICAMENTE, AS POSIÇÕES DAS CHAVES DEVEM ESTAR:', null, '[{"letra": "A", "texto": "ARMED na cabine de comando - ARMED na cabine pax", "imagem_url": null}, {"letra": "B", "texto": "ON na cabine de comando - ON na cabine de pax", "imagem_url": null}, {"letra": "C", "texto": "OFF na cabine de comando - ARMED na cabine de pax", "imagem_url": null}, {"letra": "D", "texto": "ARMED na cabine de comando  - NORMAL na cabine de pax", "imagem_url": null}]'::jsonb, 'D', null),
('anac', '3f9ed245-73f3-41c3-80cd-d58cfc488d74', 'Segurança e Emergência', null, 'SÃO PROCEDIMENTOS ROTINEIROS DE SEGURANÇA:', null, '[{"letra": "A", "texto": "não entrar na cabine de comando 05 minutos antes do pouso e 10 minutos após a decolagem", "imagem_url": null}, {"letra": "B", "texto": "não entrar na cabine de comando 10 minutos antes do pouso e 05 minutos após a decolagem", "imagem_url": null}, {"letra": "C", "texto": "entrar na cabine para avisar o comandante o número de pax a bordo 10 minutos após a decolagem", "imagem_url": null}, {"letra": "D", "texto": "entrar na cabine de comando após 05 minutos da decolagem", "imagem_url": null}]'::jsonb, 'A', null),
