('anac', '829b49f9-af5d-47fa-b0fc-db90ad9201c1', 'Segurança e Emergência', null, 'EM CASO DE TURBULÊNCIA SEVERA SÚBITA, O COMISSÁRIO DEVE, PRIORITARIAMENTE,', null, '[{"letra": "A", "texto": "FAZER O CHEQUE CRUZADO DE CABINE PARA VERIFICAR AS CONDIÇÕES DOS PASSAGEIROS, VOLUMES E OBJETOS SOLTOS", "imagem_url": null}, {"letra": "B", "texto": "CAMINHAR ATÉ A ESTAÇÃO MAIS PRÓXIMA, AFIVELAR O CINTO DE SEGURANÇA E LER O CHECKLIST DE TURBULÊNCIA", "imagem_url": null}, {"letra": "C", "texto": "FAZER O ANÚNCIO DE APERTAR CINTOS", "imagem_url": null}, {"letra": "D", "texto": "SENTAR-SE NO ASSENTO LIVRE MAIS PRÓXIMO E AFIVELAR O CINTO DE SEGURANÇA", "imagem_url": null}]'::jsonb, 'D', null),
