('anac', 'a4020647-72a7-4dda-9e01-c51b3b7e56f7', 'Segurança e Emergência', null, 'DENTRE AS COBRAS PEÇONHENTAS DAS AMÉRICAS A ÚNICA QUE NÃO POSSUI FOSSETA LOREAL É A:', null, '[{"letra": "A", "texto": "urutu", "imagem_url": null}, {"letra": "B", "texto": "jararaca", "imagem_url": null}, {"letra": "C", "texto": "surucucu", "imagem_url": null}, {"letra": "D", "texto": "coral", "imagem_url": null}]'::jsonb, 'D', null),
('anac', '8a5df4b0-cefe-40bc-a80f-433fee3da5e3', 'Segurança e Emergência', null, 'NUM POUSO DE EMERGÊNCIA PREPARADO, HAVENDO UM PASSAGEIRO PARALÍTICO A BORDO, O COMISSÁRIO DEVERÁ:', null, '[{"letra": "A", "texto": "acomodá-lo em qualquer assento, com cuidados especiais", "imagem_url": null}, {"letra": "B", "texto": "sentá-lo no corredor, próximo à porta, e instruí-lo como destravá-la", "imagem_url": null}, {"letra": "C", "texto": "acomodá-lo perto da estação de comissários, sem cuidados especiais", "imagem_url": null}, {"letra": "D", "texto": "sentá-lo em poltrona próxima a uma porta, designando um passageiro para que assista-o durante o pouso", "imagem_url": null}]'::jsonb, 'D', null),
