('anac', 'f311acc7-aa35-49cb-82b4-63ff98514f52', 'Segurança e Emergência', null, 'DURANTE A PREPARAÇÃO DOS PASSAGEIROS PARA POUSO DE EMERGÊNCIA NA ÁGUA, OS MESMOS DEVERÃO SER INSTRUÍDOS, PARA:', null, '[{"letra": "A", "texto": "recolherem seus objetos de uso pessoal, retirando apenas os óculos e quaisquer objetos pontiagudos", "imagem_url": null}, {"letra": "B", "texto": "permanecer em fila junto às saídas de emergência", "imagem_url": null}, {"letra": "C", "texto": "retirar os sapatos, óculos e outros objetos pontiagudos e vestir os coletes salva-vidas, mantendo-se sentados com os cintos atados", "imagem_url": null}, {"letra": "D", "texto": "permanecerem sentados com os cintos de segurança desatados, cabeça encostada na poltrona e sem os sapatos", "imagem_url": null}]'::jsonb, 'C', null),
