('anac', 'a3396f10-51bc-4feb-af75-021d8e4f2039', 'Segurança e Emergência', null, 'NA PREPARAÇÃO DE CABINE PARA UM POUSO DE EMERGÊNCIA, OS PAXS SÃO INSTRUÍDOS PARA ASSUMIR A POSIÇÃO DE IMPACTO:', null, '[{"letra": "A", "texto": "aeronave em voo assim que for ensinada a posição, mantendo até a parada total da aeronave", "imagem_url": null}, {"letra": "B", "texto": "quando a aeronave pousar, quando ouvirem a ordem de posição de impacto mantendo esta posição até a aeronave parar", "imagem_url": null}, {"letra": "C", "texto": "quando a aeronave pousar, ao sinal do comandante, mantendo até a parada total da aeronave", "imagem_url": null}, {"letra": "D", "texto": "ao sinal do comandante e quando ouvirem a ordem posição de impacto, mantendo esta posição até a parada total da aeronave", "imagem_url": null}]'::jsonb, 'D', null),
