('anac', 'da489588-1715-443c-ad0d-8e6390ca3d4a', 'Segurança e Emergência', null, 'NUMA SITUAÇÃO DE POUSO FORÇADO EM TERRA, AINDA A BORDO, O PROCEDIMENTO COM RELAÇÃO AOS AGASALHOS E ROUPAS DE FRIO:', null, '[{"letra": "A", "texto": "os comissários decidem de acordo com as condições atmosféricas", "imagem_url": null}, {"letra": "B", "texto": "devem ser deixados, pois levá-los dificultaria a evacuação", "imagem_url": null}, {"letra": "C", "texto": "fica a critério de cada um, dependendo do tipo de agasalho e se a pessoa sente muito frio", "imagem_url": null}, {"letra": "D", "texto": "devem ser levados, uma vez que à noite a temperatura sempre é bem mais baixa", "imagem_url": null}]'::jsonb, 'D', null),
