('anac', '8bf028c3-6d4f-4c1b-8bfc-4ece064d2517', 'Segurança e Emergência', null, 'DENTRE AS ALTERNATIVAS ABAIXO, INDIQUE A QUE SE REFERE À CLASSE DE INCÊNDIO EM QUE SE UTILIZA O EXTINTOR DE ÁGUA.', null, '[{"letra": "A", "texto": "A", "imagem_url": null}, {"letra": "B", "texto": "C", "imagem_url": null}, {"letra": "C", "texto": "B", "imagem_url": null}, {"letra": "D", "texto": "D", "imagem_url": null}]'::jsonb, 'A', null),
