('anac', 'ee33c5f7-adc5-4424-bbca-08c4e1bd37c4', 'Segurança e Emergência', null, 'O PROCEDIMENTO ADEQUADO NO CASO DE ENJÔO MARÍTIMO É:', null, '[{"letra": "A", "texto": "ingerir bastante líquido", "imagem_url": null}, {"letra": "B", "texto": "suspender a alimentação e repouso", "imagem_url": null}, {"letra": "C", "texto": "manter o indivíduo em pé para melhorar a ventilação", "imagem_url": null}, {"letra": "D", "texto": "dar atividades para que os sobreviventes se distraiam", "imagem_url": null}]'::jsonb, 'B', null),
