('anac', 'f217635c-1ebf-4235-8892-1d0c6097b239', 'Segurança e Emergência', null, 'DURANTE UMA SOBREVIVÊNCIA NA SELVA, COM A QUANTIDADE DE ÁGUA DIMINUTA, OS SOBREVIVENTES DEVERÃO DAR PREFERÊNCIA PARA COMER:', null, '[{"letra": "A", "texto": "vegetais", "imagem_url": null}, {"letra": "B", "texto": "sementes", "imagem_url": null}, {"letra": "C", "texto": "carnes", "imagem_url": null}, {"letra": "D", "texto": "ovos", "imagem_url": null}]'::jsonb, 'A', null),
