('anac', 'bddeb559-3553-4e32-b7ec-5a2d87470825', 'Segurança e Emergência', null, 'NA REGIÃO AMAZÔNICA, QUANDO DENTRO D´ÁGUA, DEVE-SE TER CUIDADO REDOBRADO COM O PEIXE PORAQUÊ, POIS O PESCADOR PODERÁ', null, '[{"letra": "A", "texto": "TER O SISTEMA URINÁRIO INVADIDO", "imagem_url": null}, {"letra": "B", "texto": "RECEBER UMA DESCARGA ELÉTRICA", "imagem_url": null}, {"letra": "C", "texto": "RECEBER FERROADAS PERIGOSAS COM A CAUDA BIFARPEADA E SUAS ASPAS RETORSAS", "imagem_url": null}, {"letra": "D", "texto": "SER ATACADO PELOS TRÊS FERRÕES QUE O PEIXE POSSUI", "imagem_url": null}]'::jsonb, 'B', null),
('anac', 'aa412fc7-8f06-4218-a279-b5e3d815f48f', 'Segurança e Emergência', null, 'EM CASO DE EMERGÊNCIA, A ILUMINAÇÃO EXTERNA DA AERONAVE ESTÁ LOCALIZADA', null, '[{"letra": "A", "texto": "JUNTO ÀS SAÍDAS, NA EMPENAGEM", "imagem_url": null}, {"letra": "B", "texto": "NA ASA E NA EMPENAGEM", "imagem_url": null}, {"letra": "C", "texto": "NO CHÃO, AO LONGO DA CABINE DE PASSAGEIROS", "imagem_url": null}, {"letra": "D", "texto": "JUNTO ÀS SAÍDAS PRINCIPAIS E DE SERVIÇO E NAS ÁREAS SOBRE AS ASAS", "imagem_url": null}]'::jsonb, 'D', null),
('anac', 'd4748592-de05-4990-9b23-2b6ac6bfab87', 'Segurança e Emergência', null, 'A RESPEITO DE ABRIGOS PARA SOBREVIVÊNCIA NA SELVA, É CORRETO AFIRMAR QUE', null, '[{"letra": "A", "texto": "A FACILIDADE DE OBTENÇÃO DE LENHA E ÁGUA, NÃO TEM QUALQUER RELAÇÃO COM A ESCOLHA DO LOCAL PARA A CONTRUÇÃO DO ABRIGO", "imagem_url": null}, {"letra": "B", "texto": "O ABRIGO IMPROVISADO MAIS FÁCIL DE ARMAR CONSISTE NUMA LONA OU COBERTOR ESTENDIDO POR CIMA DE UMA CORDA, OU DE ENTRE DUAS ÁRVORES OU DUAS ESTACAS", "imagem_url": null}, {"letra": "C", "texto": "O LOCAL PARA CONSTRUÇÃO DOS ABRIGOS(ACAMPAMENTOS) NÃO DEPENDE DO RELEVO OU PERIGO DE AVALANCHES OU INUNDAÇÕES, POIS O IMPORTANTE É SE PROTEGER O MAIS RÁPIDO POSSÍVEL", "imagem_url": null}, {"letra": "D", "texto": "DEVE-SE EVITAR CONSTRUIR ABRIGOS COM PARTES DA AERONAVE, POIS SENDO DE METAL, PODERÃO ATRAIR RAIOS EM CASO DE CHUVAS", "imagem_url": null}]'::jsonb, 'B', null),
('anac', '170e8181-4156-46e3-9b9a-47fff05fb88d', 'Segurança e Emergência', null, 'DE BRAÇOS ABERTOS, COM O BRAÇO ESQUERDO APONTADO PARA O NASCENTE (LESTE), À SUA FRENTE ESTARÁ O', null, '[{"letra": "A", "texto": "NORTE", "imagem_url": null}, {"letra": "B", "texto": "SUL", "imagem_url": null}, {"letra": "C", "texto": "OESTE", "imagem_url": null}, {"letra": "D", "texto": "NOROESTE", "imagem_url": null}]'::jsonb, 'B', null),
('anac', '3e0450b2-260b-4630-8ab7-8be3c125a931', 'Segurança e Emergência', null, 'ALGUNS PEIXES DOS RIOS BRASILEIROS SÃO PERIGOSOS. EM ESPECIAL O SOBREVIVENTE QUE ESTIVER NA ÁGUA DEVERÁ TOMAR CUIDADO COM O PORAQUÊ PORQUE ESTE PEIXE:', null, '[{"letra": "A", "texto": "é extremamente agressivo e carnívoro nada sempre em cardume", "imagem_url": null}, {"letra": "B", "texto": "possui como arma de defesa ataque descargas elétrica violenta", "imagem_url": null}, {"letra": "C", "texto": "possui ferrão na ponta da cauda que causa ferimentos profundos e que infeccionam rapidamente", "imagem_url": null}, {"letra": "D", "texto": "possui glândulas de veneno espalhadas pela pele e espinhos por todo o corpo", "imagem_url": null}]'::jsonb, 'B', null),
('anac', 'ae4e4b75-419d-4e68-92e5-a4a94ad8b5bc', 'Segurança e Emergência', null, 'NA MONTAGEM DO ACAMPAMENTO, EXISTEM CERTAS REGRAS DE HIGIENE. PORTANTO, A FOSSA PARA O LIXO DEVERÁ FICAR, EM RELAÇÃO AO ACAMPAMENTO E À FONTE DE ÁGUA,', null, '[{"letra": "A", "texto": "O MAIS PRÓXIMA POSSÍVEL", "imagem_url": null}, {"letra": "B", "texto": "A UMA DISTÂNCIA MÉDIA", "imagem_url": null}, {"letra": "C", "texto": "A QUALQUER DISTÂNCIA", "imagem_url": null}, {"letra": "D", "texto": "O MAIS DISTANTE POSSÍVEL", "imagem_url": null}]'::jsonb, 'D', null),
('anac', 'a7a354d6-1084-4c89-a355-ba8475d6a911', 'Segurança e Emergência', null, 'A MACHADINHA ENCONTRADA A BORDO DE AERONAVES É ASSIM DESCRITA:', null, '[{"letra": "A", "texto": "UM LADO CORTANTE, OUTRO PERFURANTE E CABO DE BORRACHA ISOLANTE", "imagem_url": null}, {"letra": "B", "texto": "UM LADO CORTANTE, UM SERRILHADO E CABO DE PLÁSTICO ISOLANTE", "imagem_url": null}, {"letra": "C", "texto": "UM LADO PERFURANTE, UM LADO SEM FIO E CABO DE PVC ISOLANTE", "imagem_url": null}, {"letra": "D", "texto": "DOIS LADOS PERFURANTES E PUNHO ISOLANTE DE KEVLAR", "imagem_url": null}]'::jsonb, 'A', null),
('anac', 'f5fe230d-1502-4c02-95fa-460f1a4574bd', 'Segurança e Emergência', null, 'A BIRUTA D''ÁGUA (ÂNCORA) TEM POR FINALIDADE:', null, '[{"letra": "A", "texto": "indicar a direção do vento", "imagem_url": null}, {"letra": "B", "texto": "utilizar as correntes oceânicas, em benefício dos usuários", "imagem_url": null}, {"letra": "C", "texto": "desviar o bote, afastando-o do local do acidente", "imagem_url": null}, {"letra": "D", "texto": "evitar que o bote se afaste muito do local do acidente", "imagem_url": null}]'::jsonb, 'D', null),
('anac', '08d79116-168e-4ef4-9012-0d66b884c599', 'Segurança e Emergência', null, 'O SOBREVIVENTE AO PESCAR DEVERÁ EVITAR ALIMENTAR-SE DE PEIXES QUE POSSUAM:', null, '[{"letra": "A", "texto": "formato romboidal", "imagem_url": null}, {"letra": "B", "texto": "boca semelhante a bico de papagaio", "imagem_url": null}, {"letra": "C", "texto": "muitas espinhas", "imagem_url": null}, {"letra": "D", "texto": "ferrões junto às nadadeiras dorsais e peitorais", "imagem_url": null}]'::jsonb, 'B', null),
('anac', 'bf8a1a69-7186-46f9-956e-b7c56aed593b', 'Segurança e Emergência', null, 'NÃO SE DEVE BEBER DE CACTOS OU CIPÓS CUJO SUMO SEJA', null, '[{"letra": "A", "texto": "TURVO", "imagem_url": null}, {"letra": "B", "texto": "AMARGO OU LEITOSO", "imagem_url": null}, {"letra": "C", "texto": "SALGADO", "imagem_url": null}, {"letra": "D", "texto": "ADOCICADO", "imagem_url": null}]'::jsonb, 'B', null),
('anac', 'bb235b05-40d7-4103-abfb-190347175a7b', 'Segurança e Emergência', null, 'AO VERIFICAR OS EQUIPAMENTOS DE SOBREVIVÊNCIA NO PRÉ-VOO, O COMISSÁRIO DEVERÁ TER EM MENTE QUE A RELAÇÃO QUANTIDADE DE KITS/PAX DEVERÁ SER DE:', null, '[{"letra": "A", "texto": "1 para cada 50 pax, desprezando-se as frações", "imagem_url": null}, {"letra": "B", "texto": "1 para cada 20 pax, desprezando-se as frações", "imagem_url": null}, {"letra": "C", "texto": "2 para cada 25 pax, desprezando-se as frações", "imagem_url": null}, {"letra": "D", "texto": "21 para cada 50 pax, desprezando-se as frações", "imagem_url": null}]'::jsonb, 'A', null),
('anac', '463acdda-76c0-4138-896b-7a27bab66354', 'Segurança e Emergência', null, 'ANTES DE ABANDONAR O AVIÃO, APÓS UMA EMERGÊNCIA, É DEVER DO COMISSÁRIO', null, '[{"letra": "A", "texto": "DESLIGAR O SISTEMA ELÉTRICO DAS GALLEYS", "imagem_url": null}, {"letra": "B", "texto": "DESLIGAR O SISTEMA DE LUZES DE EMERGÊNCIA", "imagem_url": null}, {"letra": "C", "texto": "FAZER O CHEQUE DE ABANDONO EM TODA A AERONAVE OU NA SUA ÁERA DESIGNADA", "imagem_url": null}, {"letra": "D", "texto": "LEVAR TODAS AS BAGAGENS DE MÃO DOS PASSAGEIROS, PARA FORA DA AERONAVE", "imagem_url": null}]'::jsonb, 'C', null),
('anac', '1fa06071-61b8-4df2-9453-b995a6a69267', 'Segurança e Emergência', null, 'OS FATORES QUE PODEM ORIGINAR UM ACIDENTE SÃO:', null, '[{"letra": "A", "texto": "técnicos, humanos, meteorológicos, casuais e desconhecidos", "imagem_url": null}, {"letra": "B", "texto": "avarias, mecânicos, fogo e colisões", "imagem_url": null}, {"letra": "C", "texto": "humanos, casuais e meteorológicos", "imagem_url": null}, {"letra": "D", "texto": "técnicos, humanos e materiais", "imagem_url": null}]'::jsonb, 'A', null),
('anac', '99c9918a-69ac-4ce0-b619-cc643c73dfa1', 'Segurança e Emergência', null, 'OS SOBREVIVENTES DE UMA AMERRISSAGEM, DEVERÃO ENCURTAR AS AMARRAS, AGRUPANDO OS BOTES SALVA-VIDAS,', null, '[{"letra": "A", "texto": "QUANDO OUVIREM OU AVISTAREM AERONAVE", "imagem_url": null}, {"letra": "B", "texto": "EM QUALQUER OCASIÃO", "imagem_url": null}, {"letra": "C", "texto": "DURANTE A NOITE PARA AQUECEREM-SE", "imagem_url": null}, {"letra": "D", "texto": "COM O MAR BEM AGITADO", "imagem_url": null}]'::jsonb, 'A', null),
('anac', '60a435ab-2acd-4b2d-b0d8-81216caca39b', 'Segurança e Emergência', null, 'O MÉTODO DE EXTINÇÃO DE INCÊNDIO, QUE CONSISTE NA RETIRADA DO MATERIAL QUE PODE SER ATINGIDO PELO FOGO, EVITANDO-SE A SUA PROPAGAÇÃO PARA OUTRAS ÁREAS, É O(A):', null, '[{"letra": "A", "texto": "SUFOCAMENTO", "imagem_url": null}, {"letra": "B", "texto": "ISOLAMENTO", "imagem_url": null}, {"letra": "C", "texto": "ABAFAMENTO", "imagem_url": null}, {"letra": "D", "texto": "RESFRIAMENTO", "imagem_url": null}]'::jsonb, 'B', null),
('anac', 'cb60ed23-c242-49f6-880e-0f6626e25766', 'Segurança e Emergência', null, 'UMA DAS FORMAS ADEQUADAS PARA O SOBREVIVENTE NO MAR CAPTURAR AVES MARINHAS É', null, '[{"letra": "A", "texto": "ESPERAR A AVE POUSAR NO BOTE E FECHAR AS ASAS, AGARRANDO-A NESTE MOMENTO", "imagem_url": null}, {"letra": "B", "texto": "USAR ESTILINGUES IMPROVISADOS, QUANDO A AVE ESTIVER PRÓXIMA", "imagem_url": null}, {"letra": "C", "texto": "COLOCAR ISCAS PENDURADAS NA BORDA DO BOTE, COM VÁRIOS ANZÓIS", "imagem_url": null}, {"letra": "D", "texto": "JOGAR OBJETOS AMARRADOS ÀS LINHAS DE PESCA, AO PASSAR UMA AVE, PARA LAÇÁ-LA", "imagem_url": null}]'::jsonb, 'A', null),
('anac', 'd8093208-27f3-46f6-867a-ee31a4738446', 'Segurança e Emergência', null, 'NUMA SOBREVIVÊNCIA NA SELVA OS SOBREVIVENTES PODERÃO UTILIZAR-SE DE BROTOS DE ALGUMAS PLANTAS PARA SUA ALIMENTAÇÃO, COM RELAÇÃO AOS BROTOS DE SAMAMBAIA, APÓS A PRIMEIRA FERVURA, DEVE-SE FERVÊ-LOS POR MAIS:', null, '[{"letra": "A", "texto": "01 hora", "imagem_url": null}, {"letra": "B", "texto": "02 horas", "imagem_url": null}, {"letra": "C", "texto": "40 minutos", "imagem_url": null}, {"letra": "D", "texto": "20 minutos", "imagem_url": null}]'::jsonb, 'C', null),
('anac', '826c8e23-8d07-4995-9b88-2d6ec01ca211', 'Segurança e Emergência', null, 'NUMA SOBREVIVÊNCIA NO MAR DEVE-SE EVITAR COMER', null, '[{"letra": "A", "texto": "LULAS", "imagem_url": null}, {"letra": "B", "texto": "BACALHAUS", "imagem_url": null}, {"letra": "C", "texto": "RAIAS", "imagem_url": null}, {"letra": "D", "texto": "MEDUSAS", "imagem_url": null}]'::jsonb, 'D', null),
('anac', 'bb0fbb0d-cbac-4e74-880f-cd79df123a08', 'Segurança e Emergência', null, 'O SISTEMA DE DETECTORES DE FUMAÇA DOS LAVATÓRIOS TEM COMO FINALIDADE INDICAR:', null, '[{"letra": "A", "texto": "a posição correta dos extintores de freon", "imagem_url": null}, {"letra": "B", "texto": "qualquer tipo de fumaça no interior do lavatório", "imagem_url": null}, {"letra": "C", "texto": "indicar luz âmbar ligada", "imagem_url": null}, {"letra": "D", "texto": "se algum passageiro acendeu cigarro no toalete", "imagem_url": null}]'::jsonb, 'B', null),
('anac', '0a1862f1-5c90-415d-b1d5-296ef31276a4', 'Segurança e Emergência', null, 'OS EQUIPAMENTOS PARA COMBATE A FOCOS DE INCÊNDIO NO AVIÃO SÃO, ALÉM DOS EXTINTORES,', null, '[{"letra": "A", "texto": "OXIGÊNIO TERAPÊUTICO E MACHADINHA", "imagem_url": null}, {"letra": "B", "texto": "LUVAS DE AMIANTO, CAPUZES ANTI-FUMAÇA E MACHADINHA", "imagem_url": null}, {"letra": "C", "texto": "GARRAFAS DE OXIGÊNIO, LUVAS DE AMIANTO E ÓCULOS CONTRA FUMAÇA", "imagem_url": null}, {"letra": "D", "texto": "ÓCULOS CONTRA FUMAÇA E MÁSCARAS ORONASAIS", "imagem_url": null}]'::jsonb, 'B', null),
('anac', 'f654412a-070b-4485-8b4f-b9d7d3e8c01d', 'Segurança e Emergência', null, 'MARQUE A ALTERNATIVA QUE TRAZ OS DOCUMENTOS REFERENTES À SEGURANÇA DA AVIAÇÃO CIVIL CONTRA ATOS DE INTERFERÊNCIA ILÍCITA.', null, '[{"letra": "A", "texto": "RBAC 108 E ANEXO 17", "imagem_url": null}, {"letra": "B", "texto": "RBAC 128 E ANEXO 18", "imagem_url": null}, {"letra": "C", "texto": "RBAC 133 E ANEXO 19", "imagem_url": null}, {"letra": "D", "texto": "RBAC 140 E ANEXO 20", "imagem_url": null}]'::jsonb, 'A', null),
('anac', 'a11e9f6f-88b3-4e8f-8a49-87fc66a6b58d', 'Segurança e Emergência', null, 'UMA AERONAVE LOCALIZOU UM ACAMPAMENTO DE SOBREVIVENTES, ESTES FIZERAM AS SINALIZAÇÕES PRESCRITAS E A AERONAVE FEZ UMA CURVA DE 360º PELA DIREITA. ESTA MANOBRA SIGNIFICA:', null, '[{"letra": "A", "texto": "MENSAGEM ENTENDIDA", "imagem_url": null}, {"letra": "B", "texto": "MENSAGEM RECEBIDA E NÃO ENTENDIDA", "imagem_url": null}, {"letra": "C", "texto": "MENSAGEM NÃO RECEBIDA", "imagem_url": null}, {"letra": "D", "texto": "AVISTADOS", "imagem_url": null}]'::jsonb, 'B', null),
('anac', '2e382f10-331d-4718-af97-30f44b3729d8', 'Segurança e Emergência', null, 'PARA MELHORAR ACOMODAÇÃO DOS PASSAGEIROS, EM SITUAÇÃO NORMAL, E COMO PREVENÇÃO CONTRA UMA POSSÍVEL EMERGÊNCIA, AS BAGAGENS DE MÃO DEVEM SER ACOMODADAS:', null, '[{"letra": "A", "texto": "dentro de toaletes, em um compartimento no teto", "imagem_url": null}, {"letra": "B", "texto": "nos compartimentos apropriados sobre as poltronas e dentro dos toaletes", "imagem_url": null}, {"letra": "C", "texto": "em um espaço reservado ao lado de galley", "imagem_url": null}, {"letra": "D", "texto": "embaixo da poltrona à frente do passageiro e nos compartimentos apropriados (gavetões)", "imagem_url": null}]'::jsonb, 'D', null),
('anac', 'c33452d0-8e97-45f6-8c9e-1dc9f2be97f8', 'Segurança e Emergência', null, 'A MELHOR MANEIRA DE SE CONSTRUIR UMA FOGUEIRA, DE MANEIRA EFICIENTE E PROTEGIDA DO VENTO É:', null, '[{"letra": "A", "texto": "no meio de arbustos para proteção contra o vento", "imagem_url": null}, {"letra": "B", "texto": "próximo aos destroços da aeronave para utilizar o combustível", "imagem_url": null}, {"letra": "C", "texto": "próximo a uma rocha ou de um anteparo feito de tronco", "imagem_url": null}, {"letra": "D", "texto": "no meio do acampamento para que assim os sobreviventes formem uma barreira de proteção", "imagem_url": null}]'::jsonb, 'C', null),
('anac', 'edf46f54-a90d-49d4-808b-8a3ea666f086', 'Segurança e Emergência', null, 'NUMA SOBREVIVÊNCIA NA SELVA, PARA SE SINALIZAR COM FOGUETES PIROTÉCNICO, DEVE-SE SEGURÁ-LO:', null, '[{"letra": "A", "texto": "a 45º em relação à linha do horizonte e contra o vento", "imagem_url": null}, {"letra": "B", "texto": "a 45º em relação à linha do horizonte e a favor do vento", "imagem_url": null}, {"letra": "C", "texto": "na posição horizontal", "imagem_url": null}, {"letra": "D", "texto": "na posição vertical", "imagem_url": null}]'::jsonb, 'B', null),
('anac', '67baeea7-0556-426b-af14-9bc003b6fe9b', 'Segurança e Emergência', null, 'OS ALIMENTOS SILVESTRES ANTES DE SEREM INGERIDOS DEVEM SER COZIDOS PORQUE:', null, '[{"letra": "A", "texto": "ficam mais saborosos e oferecem menos perigo", "imagem_url": null}, {"letra": "B", "texto": "a maioria das pessoas têm o hábito de ingerir alimentos cozidos", "imagem_url": null}, {"letra": "C", "texto": "a baixa temperatura na selva requer alimentos quentes", "imagem_url": null}, {"letra": "D", "texto": "mantém certo valor nutritivo e oferecem menos perigo", "imagem_url": null}]'::jsonb, 'D', null),
('anac', '5c5696cf-c87a-4a7f-a0eb-07afd52d92a0', 'Segurança e Emergência', null, 'QUANDO, NUM ACAMPAMENTO INDÍGENA, DEVE-SE:', null, '[{"letra": "A", "texto": "procurar conhecer todos os hábitos e costumes, visitando todos os recantos", "imagem_url": null}, {"letra": "B", "texto": "não comer de sua comida, uma vez que não se sabe a sua origem e forma de ser feita", "imagem_url": null}, {"letra": "C", "texto": "respeitar os costumes e hábitos dos índios, principalmente, os religiosos", "imagem_url": null}, {"letra": "D", "texto": "dar presentes aos índios, a todos o momento, para que eles não se tornem hostis", "imagem_url": null}]'::jsonb, 'C', null),
('anac', '18b0f96f-a805-48d9-a9f9-1cf1645beeb1', 'Segurança e Emergência', null, 'AS SAÍDAS DE EMERGÊNCIA DO TIPO I SÃO AS', null, '[{"letra": "A", "texto": "PORTAS E JANELAS OPERATIVAS", "imagem_url": null}, {"letra": "B", "texto": "PORTAS COM ESCORREGADEIRAS INFLÁVEIS", "imagem_url": null}, {"letra": "C", "texto": "JANELAS DO COCKPIT", "imagem_url": null}, {"letra": "D", "texto": "JANELAS COM ESCORREGADEIRAS INFLADAS", "imagem_url": null}]'::jsonb, 'B', null),
('anac', '1599a105-7f0c-4a11-96d5-9fc85714b809', 'Segurança e Emergência', null, 'MARQUE A OPÇÃO QUE SE REFERE A UM IMPORTANTE ITEM A SER PROVIDENCIADO PELOS SOBREVIVENTES DE UM POUSO FORÇADO NA SELVA, JÁ NO MOMENTO DA MONTAGEM DO ACAMPAMENTO.', null, '[{"letra": "A", "texto": "ARAPUCAS E OUTRAS ARMADILHAS MONTADAS A UMA CERTA DISTÂNCIA", "imagem_url": null}, {"letra": "B", "texto": "SORO FISIOLÓGICO", "imagem_url": null}, {"letra": "C", "texto": "REPELENTES CONTRA INSETOS", "imagem_url": null}, {"letra": "D", "texto": "FOGUEIRAS ARMADAS A UMA CERTA DISTÂNCIA", "imagem_url": null}]'::jsonb, 'D', null),
('anac', '84a53643-f2bb-4abc-b5db-ad12aabba12e', 'Segurança e Emergência', null, 'UM COMISSÁRIO DEVE TER EM MENTE TRÊS PRINCÍPIOS BÁSICOS PARA ATUAR COM SEGURANÇA EM CASO DE FOGO A BORDO:', null, '[{"letra": "A", "texto": "vigilância - extinção - prevenção", "imagem_url": null}, {"letra": "B", "texto": "prevenção salvamento - combate", "imagem_url": null}, {"letra": "C", "texto": "prevenção - extinção - combate", "imagem_url": null}, {"letra": "D", "texto": "contenção de pânico, salvamento-prevenção", "imagem_url": null}]'::jsonb, 'B', null),
('anac', '4d3f1066-6234-4cf5-8f93-44d51172d975', 'Segurança e Emergência', null, 'OS PEIXES MARINHOS QUE NÃO DEVEM SER INGERIDOS, POR APRESENTAREM RISCOS DE ENVENENAMENTO, SÃO OS QUE APRESENTAM PELE:', null, '[{"letra": "A", "texto": "viscosa", "imagem_url": null}, {"letra": "B", "texto": "escamosa", "imagem_url": null}, {"letra": "C", "texto": "branca", "imagem_url": null}, {"letra": "D", "texto": "com espinhos", "imagem_url": null}]'::jsonb, 'D', null),
