('anac', '9b885544-70b6-4257-bdb7-0b0eedcf5a9c', 'Segurança e Emergência', null, 'HAVENDO VAZAMENTO DE PRESSÃO POR UMA DAS PORTAS DA AERONAVE, O COMISSÁRIO DEVE:', null, '[{"letra": "A", "texto": "avisar os comandantes e retiras paxs da área", "imagem_url": null}, {"letra": "B", "texto": "colocar panos úmidos", "imagem_url": null}, {"letra": "C", "texto": "evacuar a cabine", "imagem_url": null}, {"letra": "D", "texto": "sentar e colocar o cinto", "imagem_url": null}]'::jsonb, 'A', null),
