('anac', '4e55adfa-f507-4e6b-93bd-9b9ebb63aa7e', 'Segurança e Emergência', null, 'QUANDO O SOBREVIVENTE FOR DORMIR, DEVE PROCURAR CONSTRUIR A CAMA:', null, '[{"letra": "A", "texto": "no chão; não é necessário maiores cuidados, uma vez que a fogueira espanta os animais", "imagem_url": null}, {"letra": "B", "texto": "próximo ao leito de um rio, assim fica fácil o acesso ao mesmo", "imagem_url": null}, {"letra": "C", "texto": "sobre as árvores, evitando-se assim os animais rasteiros e a umidade", "imagem_url": null}, {"letra": "D", "texto": "utilizando folhas e sobre estas, colocar mais folhas largas, ficando distante do solo", "imagem_url": null}]'::jsonb, 'D', null),
