('anac', '6e429a44-4e18-4c88-9f54-864b6704cdbc', 'Segurança e Emergência', null, 'PARA ATUAR COM SUCESSO NUMA SITUAÇÃO DE EMERGÊNCIA DEVE-SE ANTES:', null, '[{"letra": "A", "texto": "estar familiarizado com todo o equipamento que se tem à disposição", "imagem_url": null}, {"letra": "B", "texto": "saber apenas como se operam as escorregadeiras e saídas de emergência", "imagem_url": null}, {"letra": "C", "texto": "estar familiarizado com os outros tripulantes e também com as saídas de emergência", "imagem_url": null}, {"letra": "D", "texto": "saber apenas onde estão localizados os extintores, máscaras, megafones e machadinhas", "imagem_url": null}]'::jsonb, 'A', null),
