('anac', '3cdc73fc-bcc2-478a-bef1-4dc72f8c655a', 'Segurança e Emergência', null, 'OS PASSAGEIROS NA IMINÊNCIA DE POUSO NO MAR, DEVERÃO SER ORIENTADOS A:', null, '[{"letra": "A", "texto": "utilizar as saídas mais próximas de seus lugares", "imagem_url": null}, {"letra": "B", "texto": "para deixar a bordo todos os agasalhos e sapatos", "imagem_url": null}, {"letra": "C", "texto": "como colocar, usar, inflar os coletes", "imagem_url": null}, {"letra": "D", "texto": "a não comer nem beber nada mais, porque poderão enjoar", "imagem_url": null}]'::jsonb, 'C', null),
