('anac', '3e2f751a-29cf-4e0e-894a-7fabc39bed35', 'Segurança e Emergência', null, 'EM UM POUSO FORÇADO NO MAR, TENDO ABANDONADO O AVIÃO, OS SOBREVIVENTES DEVEM', null, '[{"letra": "A", "texto": "MANTER-SE SOBRE AS ASAS E EMPENAGEM DO AVIÃO", "imagem_url": null}, {"letra": "B", "texto": "FLUTUAR PRÓXIMO À AERONAVE", "imagem_url": null}, {"letra": "C", "texto": "FLUTUAR NAS ÁREAS COBERTAS DE COMBUSTÍVEL, POIS ESTARÃO PROTEGIDOS DE ATAQUES DE TUBARÕES", "imagem_url": null}, {"letra": "D", "texto": "MANTER-SE RELATIVAMENTE AFASTADOS DA AERONAVE ATÉ QUE ELA AFUNDE", "imagem_url": null}]'::jsonb, 'D', null),
