('anac', '80eabf3a-24e5-4e96-b956-6c06ee23b100', 'Segurança e Emergência', null, 'PARA QUE O COMISSÁRIO POSSA ATUAR COM SUCESSO EM UMA SITUAÇÃO DE EMERGÊNCIA DEVE-SE ANTES DE TUDO ESTAR FAMILIARIZADO COM:', null, '[{"letra": "A", "texto": "toda tripulação", "imagem_url": null}, {"letra": "B", "texto": "as saídas de emergência", "imagem_url": null}, {"letra": "C", "texto": "os equipamentos de combate a incêndio", "imagem_url": null}, {"letra": "D", "texto": "os equipamentos de emergência disponíveis a bordo", "imagem_url": null}]'::jsonb, 'D', null),
('anac', '75e9068d-5990-45a3-9a82-74612fadbdf7', 'Segurança e Emergência', null, 'A MANEIRA DE SE EVITAR A COMBUSTÃO ESPONTÂNEA É ARRUMAR OS PRODUTOS SUJEITOS A ESSAS REAÇÕES, EM, COMPARTIMENTOS:', null, '[{"letra": "A", "texto": "hermeticamente fechados", "imagem_url": null}, {"letra": "B", "texto": "quentes e fechados", "imagem_url": null}, {"letra": "C", "texto": "com pouca ventilação", "imagem_url": null}, {"letra": "D", "texto": "frescos e ventilados", "imagem_url": null}]'::jsonb, 'A', null),
('anac', '83d80418-7679-41e0-84fc-30be61074b1e', 'Segurança e Emergência', null, 'A DINÂMICA DE IMPACTO EM POUSO OU DECOLAGEM SERÁ VERIFICAR A OPERATIVIDADE DA SAÍDA E:', null, '[{"letra": "A", "texto": "aguardar comunicação de outro tripulante para abrir a  porta", "imagem_url": null}, {"letra": "B", "texto": "abrir a porta e gritar para que os paxs saltem e escorreguem", "imagem_url": null}, {"letra": "C", "texto": "abrir a porta e aguardar ordem para desembarcar os paxs", "imagem_url": null}, {"letra": "D", "texto": "abrir a porta, inflar escorregadeira, gritar para que os paxs saltem", "imagem_url": null}]'::jsonb, 'D', null),
('anac', 'a731f308-9316-4a21-9c59-28d5ee2d8a3c', 'Segurança e Emergência', null, 'ENTRE OS PEIXES PERIGOSOS DE NOSSOS RIOS DEVE-SE TER CUIDADO COM OS MANDIS PORQUE:', null, '[{"letra": "A", "texto": "possuem ferrões junto às nadadeiras dorsais e peitorais", "imagem_url": null}, {"letra": "B", "texto": "possuem carga elétrica", "imagem_url": null}, {"letra": "C", "texto": "possuem ferrão na ponta da causa", "imagem_url": null}, {"letra": "D", "texto": "são carnívoros", "imagem_url": null}]'::jsonb, 'A', null),
('anac', 'd95ad8ff-9174-48a9-a9e2-89a210f6a729', 'Segurança e Emergência', null, 'EM FUNÇÃO DA EFICIÊNCIA E DA SEGURANÇA, NUMA SOBREVIVÊNCIA NO MAR, O SISTEMA DE VIGÍLIA POR TURNO DEVERÁ SER DE, NO MÁXIMO,', null, '[{"letra": "A", "texto": "6 HORAS", "imagem_url": null}, {"letra": "B", "texto": "2 HORAS", "imagem_url": null}, {"letra": "C", "texto": "5 HORAS", "imagem_url": null}, {"letra": "D", "texto": "4 HORAS", "imagem_url": null}]'::jsonb, 'B', null),
('anac', '774f624d-56ce-48d9-aba8-6f50f79f13f5', 'Segurança e Emergência', null, 'HAVENDO UM FOCO DE INCÊNDIO EM UM TOALETE E ESTANDO A PORTA DO MESMO MUITO QUENTE, ANTES DE ABRI-LA PARA COMBATER O FOGO, DEVE-SE:', null, '[{"letra": "A", "texto": "vestir um capuz antifumaça e entrar, imediatamente no toalete", "imagem_url": null}, {"letra": "B", "texto": "abrir uma fresta ou fazer um furo na parte superior da porta do toalete, e descarregar um extintor de halon, de preferência", "imagem_url": null}, {"letra": "C", "texto": "informar aos passageiros todos os procedimentos que serão adotados para que os mesmos permaneçam calmos", "imagem_url": null}, {"letra": "D", "texto": "solicitar a um tripulante técnico, instruções sobre os procedimentos que deverão ser adotados", "imagem_url": null}]'::jsonb, 'B', null),
('anac', 'd2e13558-65b3-4753-9283-331e0f5ceda7', 'Segurança e Emergência', null, 'O DESLOCAMENTO NA SELVA PODERÁ SER FEITO, DEDE QUE:', null, '[{"letra": "A", "texto": "o trajeto percorrido seja marcado", "imagem_url": null}, {"letra": "B", "texto": "seja feito de barco", "imagem_url": null}, {"letra": "C", "texto": "esteja-se munido de um bússola", "imagem_url": null}, {"letra": "D", "texto": "seja feito em caráter definitivo", "imagem_url": null}]'::jsonb, 'A', null),
('anac', '52414c6d-6497-4724-9dd1-b9f232f0fcd3', 'Segurança e Emergência', null, 'EM UMA SOBREVIVÊNCIA NO MAR, CASO O SOBREVIVENTE CONSIGA CAÇAR UMA GAIVOTA OU PESCAR UM PEIXE, ELE DEVE:', null, '[{"letra": "A", "texto": "mascar a sua carne após escorrer o seu sangue", "imagem_url": null}, {"letra": "B", "texto": "beber o sangue e comer a carne crua", "imagem_url": null}, {"letra": "C", "texto": "mascar a sua carne e beber o seu sangue", "imagem_url": null}, {"letra": "D", "texto": "fazer um fogo e assá-lo", "imagem_url": null}]'::jsonb, 'C', null),
('anac', '7fe480b9-c35d-478d-9bfc-41f87821fefe', 'Segurança e Emergência', null, 'PREPARANDO-SE PARA UM POUSO DE EMERGÊNCIA, OS COMISSÁRIOS DEVERÃO VERIFICAR A(AS):', null, '[{"letra": "A", "texto": "posição de impacto dos passageiros", "imagem_url": null}, {"letra": "B", "texto": "pax com cintos atados, mesinhas travadas, encostos das poltronas na posição vertical", "imagem_url": null}, {"letra": "C", "texto": "posição de impacto dos tripulantes", "imagem_url": null}, {"letra": "D", "texto": "extintores de incêndio", "imagem_url": null}]'::jsonb, 'B', null),
('anac', '554b3d00-01d9-4041-9805-06d36f0bb479', 'Segurança e Emergência', null, 'OS PEIXES QUE NÃO DEVEM-SER INGERIDOS, POR APRESENTAREM RISCOS DE ENVENENAMENTO, SÃO OS QUE TEM A PELE', null, '[{"letra": "A", "texto": "VISCOSA", "imagem_url": null}, {"letra": "B", "texto": "COM ESPINHOS", "imagem_url": null}, {"letra": "C", "texto": "BRANCA", "imagem_url": null}, {"letra": "D", "texto": "ESCAMOSA", "imagem_url": null}]'::jsonb, 'B', null),
('anac', 'd4204540-4f1a-4dd9-b7a3-7b5c840a0447', 'Segurança e Emergência', null, 'ASSINALE A ALTERNATIVA CORRETA:', null, '[{"letra": "A", "texto": "abafamento é o método de extinguir o fogo pela retirada de calor", "imagem_url": null}, {"letra": "B", "texto": "a condução é a transmissão de calor através da massa de ar", "imagem_url": null}, {"letra": "C", "texto": "o extintor de água é indicado para o fago de classe C", "imagem_url": null}, {"letra": "D", "texto": "condução é a transmissão de calor de molécula à molécula", "imagem_url": null}]'::jsonb, 'D', null),
('anac', '6f6eef26-a123-46a4-a18b-fe18e921f81a', 'Segurança e Emergência', null, 'NAS DECOLAGENS E POUSOS, COMO MEDIDA DE SEGURANÇA, É DEVER DOS COMISSÁRIOS VERIFICAR SE', null, '[{"letra": "A", "texto": "TODOS OS PASSAGEIROS ESTÃO NA POSIÇÃO DE IMPACTO", "imagem_url": null}, {"letra": "B", "texto": "AS LUZES DE LEITURA ESTÃO LIGADAS", "imagem_url": null}, {"letra": "C", "texto": "OS PASSAGEIROS ESTÃO COM O CINTO DE SEGURANÇA ATADO, A MESINHA FECHADA E POLTRONA NA POSIÇÃO HORIZONTAL", "imagem_url": null}, {"letra": "D", "texto": "OS PASSAGEIROS ESTÃO COM O CINTO DE SEGURANÇA ATADO, MESINHA FECHADA E TRAVADA E POLTRONA NA POSIÇÃO VERTICAL", "imagem_url": null}]'::jsonb, 'D', null),
('anac', 'c2893f70-74d3-48f2-9bf0-a7b0b3b28450', 'Segurança e Emergência', null, 'À NOITE OU COM NEVOEIRO, USA-SE O APITO NO BOTE SALVA-VIDAS PARA', null, '[{"letra": "A", "texto": "AFASTAR PEIXES DE GRANDE PORTE QUE ESTEJAM AMEAÇANDO A SEGURANÇA DO BOTE", "imagem_url": null}, {"letra": "B", "texto": "TRANSMITIR CÓDIGO ENTRE OS BOTES, APENAS", "imagem_url": null}, {"letra": "C", "texto": "ATRAIR A ATENÇÃO DE NAVIOS OU PESSOAS NA PRAIA", "imagem_url": null}, {"letra": "D", "texto": "ATRAIR A ATENÇÃO DE AVIÕES DE BUSCA OU QUALQUER OUTRA AERONAVE QUE PASSE POR PERTO", "imagem_url": null}]'::jsonb, 'C', null),
('anac', 'cbef7087-6821-4aa7-b9c4-b6ee4fdf1f6f', 'Segurança e Emergência', null, 'DURANTE TODA A OPERAÇÃO, O ALERTA SITUACIONAL FAZ PARTE DA ROTINA DOS TRIPULANTES. É RECOMENDÁVEL QUE, DURANTE O PROCEDIMENTO DE DECOLAGEM E POUSO, O (A) COMISSÁRIO (A)', null, '[{"letra": "A", "texto": "FAÇA UMA REVISÃO MENTAL DOS PROCEDIMENTOS DE EMERGÊNCIA", "imagem_url": null}, {"letra": "B", "texto": "CHAME A CABINE DE COMANDO PARA VERIFICAÇÕES FINAIS", "imagem_url": null}, {"letra": "C", "texto": "CHAME AS ESTAÇÕES DE COMISSÁRIO PARA CONFERÊNCIA", "imagem_url": null}, {"letra": "D", "texto": "LEIA AS INSTRUÇÕES DE SEGURANÇA", "imagem_url": null}]'::jsonb, 'A', null),
('anac', '914b94c5-58e4-4612-92d0-206ed960b5fd', 'Segurança e Emergência', null, 'SE ESTIVER DISTANTE DE UMA ESTAÇÃO DE COMISSÁRIOS E HOUVER UMA DESPRESSURIZAÇÃO SÚBITA, O COMISSÁRIO DEVE', null, '[{"letra": "A", "texto": "PEGAR QUALQUER DAS GARRAFAS DE OXIGÊNIO, AUXILIANDO IMEDIATAMENTE OS PASSAGEIROS", "imagem_url": null}, {"letra": "B", "texto": "PEGAR A MÁSCARA DE OXIGÊNIO MAIS PRÓXIMA, COLOCÁ-LA E AGUARDAR O NIVELAMENTO DE SEGURANÇA DA AERONAVE", "imagem_url": null}, {"letra": "C", "texto": "BUSCAR DE IMEDIATO A GARRAFA DE OXIGÊNIO COM MÁSCARA ORONASAL E AUXILIAR OS PASSAGEIROS", "imagem_url": null}, {"letra": "D", "texto": "PUXAR AS MÁSCARAS DE OXIGÊNIO QUE ESTEJAM MAIS PRÓXIMAS, COLOCANDO-AS NOS PASSAGEIROS E, A SEGUIR, COLOCAR A PRÓPRIA", "imagem_url": null}]'::jsonb, 'B', null),
('anac', 'cf4d83ff-99cd-429c-a903-97916afbff4e', 'Segurança e Emergência', null, 'OS CARRAPATOS SÃO ENCONTRADOS FREQUENTEMENTE EM:', null, '[{"letra": "A", "texto": "lugares úmidos", "imagem_url": null}, {"letra": "B", "texto": "capinzais", "imagem_url": null}, {"letra": "C", "texto": "lagoas", "imagem_url": null}, {"letra": "D", "texto": "árvores secas", "imagem_url": null}]'::jsonb, 'B', null),
('anac', '44910e20-e5b8-46aa-ac9c-71892ef8b040', 'Segurança e Emergência', null, 'NA EVENTUALIDADE DE SE PROMOVER O EMBARQUE OU DESEMBARQUE DOS PASSAGEIROS COM UM DOS MOTORES EM FUNCIONAMENTO, EM QUALQUER TIPO DE AERONAVE, DEVE-SE:', null, '[{"letra": "A", "texto": "direcionar os passageiros para o lado oposto do motor em questão", "imagem_url": null}, {"letra": "B", "texto": "adotar os procedimentos de uma operação normal", "imagem_url": null}, {"letra": "C", "texto": "aguardar a autorização da manutenção", "imagem_url": null}, {"letra": "D", "texto": "impedir o embarque ou o desembarque pelas portas traseiras", "imagem_url": null}]'::jsonb, 'A', null),
('anac', '2f4df001-8ef5-4d4c-aa04-13e3ec617973', 'Segurança e Emergência', null, 'OS EQUIPAMENTOS QUE PODERÃO SER DANIFICADOS COM A UMIDADE DO BOTE, NUMA SOBREVIVÊNCIA NO MAR SÃO:', null, '[{"letra": "A", "texto": "apito, espelho sinalizador e kit de primeiros-socorros", "imagem_url": null}, {"letra": "B", "texto": "bússola, relógio, fósforo e sinalizador pirotécnico", "imagem_url": null}, {"letra": "C", "texto": "balde de lona, bomba manual e botijões de vedação", "imagem_url": null}, {"letra": "D", "texto": "garrafa de ar comprimido e kit de primeiros-socorros", "imagem_url": null}]'::jsonb, 'B', null),
