('anac', '41ff456f-38e8-423e-874f-429e49d4df56', 'Segurança e Emergência', null, 'O VENENO DO ESCORPIÃO É:', null, '[{"letra": "A", "texto": "somente doloroso por 24h", "imagem_url": null}, {"letra": "B", "texto": "somente doloroso por 48h", "imagem_url": null}, {"letra": "C", "texto": "totalmente mortal", "imagem_url": null}, {"letra": "D", "texto": "doloroso de 4 a 6h", "imagem_url": null}]'::jsonb, 'D', null),
('anac', '5f2290dd-3862-4b2b-b3cc-63885ad3c092', 'Segurança e Emergência', null, 'PARA MELHOR LOCALIZAÇÃO NA SELVA, DURANTE O DIA, DEVE SE COLOCAR NA ASA E AO REDOR DO AVIÃO', null, '[{"letra": "A", "texto": "objetos que se confundem com o verde das árvores", "imagem_url": null}, {"letra": "B", "texto": "chapas de carenagens com o lado pintado virado para cima, pois, constituem bons refletores", "imagem_url": null}, {"letra": "C", "texto": "objetos brilhantes e de coloração viva", "imagem_url": null}, {"letra": "D", "texto": "lanternas elétricas", "imagem_url": null}]'::jsonb, 'C', null),
('anac', '87c8d3da-3a37-4b8c-9d28-c574aa819402', 'Segurança e Emergência', null, 'HAVENDO ALIJA MENTO DE COMBUSTÍVEL O COMISSÁRIO DEVERÁ AVISAR AOS PAXS QUANTO A:', null, '[{"letra": "A", "texto": "não acender, nem ligar luzes individuais ou usar objeto que produza faísca", "imagem_url": null}, {"letra": "B", "texto": "desembarcar rapidamente para evitar danos maiores", "imagem_url": null}, {"letra": "C", "texto": "escorregar e saltar pelos escapes slides", "imagem_url": null}, {"letra": "D", "texto": "colocar as bandejas de alimentos no chão", "imagem_url": null}]'::jsonb, 'A', null),
('anac', '2ac807de-f765-468d-92c0-4a33edac3d93', 'Segurança e Emergência', null, 'PARA SE EXTINGUIR O FOGO EM COMBUSTÍVEL GASOSO, DEVE-SE:', null, '[{"letra": "A", "texto": "desligar o quadro de força, pois, assim, um incêndio classificado como da Classe C, se extinguira, pelo método de isolamento", "imagem_url": null}, {"letra": "B", "texto": "utilizar o método de resfriamento, abaixando a temperatura do gás, o fogo extinguir-se-á", "imagem_url": null}, {"letra": "C", "texto": "utilizar de métodos de abafamento, tomando-se a precaução de cortar o fornecimento do gás", "imagem_url": null}, {"letra": "D", "texto": "cortar o fornecimento do gás, quebrando-se o equilíbrio do triângulo, pela retirada do material combustível", "imagem_url": null}]'::jsonb, 'D', null),
('anac', '06e496f0-b935-48bc-85b2-d98b59d3ce7b', 'Segurança e Emergência', null, 'COMO PREVENÇÃO DE PÂNICO A BORDO, MEDIANTE RECEIO DE VOAR, REALIZA-SE', null, '[{"letra": "A", "texto": "informações ao paxs sobre o perigo que uma aeronave oferece", "imagem_url": null}, {"letra": "B", "texto": "informações do cock pit sobre pontos conhecidos sobrevoados", "imagem_url": null}, {"letra": "C", "texto": "conscientização dos paxs quanto aos perigos iminentes", "imagem_url": null}, {"letra": "D", "texto": "serviço a bordo, desenvolvimento de programa de diversão a bordo", "imagem_url": null}]'::jsonb, 'D', null),
('anac', '7102154c-8a46-47ca-9dca-51e6f31dae79', 'Segurança e Emergência', null, 'A POSIÇÃO DE IMPACTO QUE O COMISSÁRIO DEVE ADOTAR NUM POUSO DE EMERGÊNCIA, ESTANDO SENTADO DE FRENTE PARA O NARIZ DA AERONAVE É:', null, '[{"letra": "A", "texto": "braços cruzados e cabeça fletida para trás", "imagem_url": null}, {"letra": "B", "texto": "cabeça para frente e queixo tracionado contra o pescoço", "imagem_url": null}, {"letra": "C", "texto": "cinto de inércia, braços cruzados e cabeça baixa", "imagem_url": null}, {"letra": "D", "texto": "pescoço pressionado para trás", "imagem_url": null}]'::jsonb, 'C', null),
('anac', '0f7436bd-2589-4859-b87a-6f91114d144c', 'Segurança e Emergência', null, 'INDIQUE A ALTERNATIVA CORRETA:', null, '[{"letra": "A", "texto": "combustível é todo material líquido", "imagem_url": null}, {"letra": "B", "texto": "o oxigênio é um comburente", "imagem_url": null}, {"letra": "C", "texto": "PQS é um agente extintor formado por água", "imagem_url": null}, {"letra": "D", "texto": "abafamento é a retirada de calor", "imagem_url": null}]'::jsonb, 'B', null),
('anac', '21151ebf-3964-496d-8e06-46c16e7b3ddd', 'Segurança e Emergência', null, 'NUMA AMERRISSAGEM, OS COLETES SALVA-VIDAS DEVERÃO', null, '[{"letra": "A", "texto": "ESTAR VESTIDOS, MAS INFLADOS APÓS SALTAR NO MAR", "imagem_url": null}, {"letra": "B", "texto": "ESTAR VESTIDOS E SEREM INFLADOS NA SOLEIRA DA PORTA, AO ABANDONAR A AERONAVE", "imagem_url": null}, {"letra": "C", "texto": "SER USADOS APENAS PELOS PASSAGEIROS QUE NÃO SOUBEREM NADAR", "imagem_url": null}, {"letra": "D", "texto": "SER VESTIDOS E INFLADOS IMEDIATAMENTE", "imagem_url": null}]'::jsonb, 'B', null),
('anac', 'bf2bc622-eec1-447f-8a0c-f2ebfc9324a2', 'Primeiros Socorros', null, 'A HEMORRAGIA ARTERIAL, POR SER GRAVE, E NÃO COIBIDA, DEVE SER TRATADA:', null, '[{"letra": "A", "texto": "com compressão por 05 minutos", "imagem_url": null}, {"letra": "B", "texto": "lavando-se o ferimento", "imagem_url": null}, {"letra": "C", "texto": "usando-se o garrote com afrouxamento a cada 15 min", "imagem_url": null}, {"letra": "D", "texto": "com compressão por 15 minutos", "imagem_url": null}]'::jsonb, 'C', null),
