('anac', 'c3b06f42-850a-4559-8e2e-b3b488770e0f', 'Segurança e Emergência', null, 'NO CASO DO CINTO DE SEGURANÇA NÃO SER SUFICIENTE PARA TRAVAR AO REDOR DA CINTURA DO PAX, O COMISSÁRIO DEVERÁ:', null, '[{"letra": "A", "texto": "informar ao despacho de terra que o acomodará em outra aeronave", "imagem_url": null}, {"letra": "B", "texto": "avisar ao comandante e o pax será acomodado na cabine de comando no jump seat", "imagem_url": null}, {"letra": "C", "texto": "comunicar ao comandante e o pax é liberado do seu uso", "imagem_url": null}, {"letra": "D", "texto": "providenciar um cinto extensório", "imagem_url": null}]'::jsonb, 'D', null),
('anac', 'cabf28eb-d50b-4186-9b6f-d97c76d382b5', 'Segurança e Emergência', null, 'AO SAIR DA AERONAVE POR UMA SAÍDA DE EMERGÊNCIA SOBRE A ASA DEVE-SE ESCORREGAR PELO: (BOEING 737-300)', null, '[{"letra": "A", "texto": "flap do bordo de fuga da asa", "imagem_url": null}, {"letra": "B", "texto": "escape slide, pista dupla", "imagem_url": null}, {"letra": "C", "texto": "escape slide, pista simples", "imagem_url": null}, {"letra": "D", "texto": "borda de ataque", "imagem_url": null}]'::jsonb, 'A', null),
('anac', '5baf83a1-76fb-406c-a7c3-a533a27891a1', 'Segurança e Emergência', null, 'O MÉTODO DE EXTINÇÃO DE FOGO, MAIS UTILIZADO, E QUE CONSISTE EM SE RETIRAR CALOR DO MATERIAL EM COMBUSTÃO, É O MÉTODO DE:', null, '[{"letra": "A", "texto": "resfriamento", "imagem_url": null}, {"letra": "B", "texto": "abafamento", "imagem_url": null}, {"letra": "C", "texto": "isolamento", "imagem_url": null}, {"letra": "D", "texto": "quebra da reação em cadeia", "imagem_url": null}]'::jsonb, 'A', null),
('anac', 'a173899a-9998-4152-8d74-79c263f62279', 'Segurança e Emergência', null, 'O MÉTODO DE EXTINÇÃO DE FOGO QUE CONSISTE EM REDUZIR O CALOR É O DE', null, '[{"letra": "A", "texto": "QUEBRA DE REAÇÃO EM CADEIA", "imagem_url": null}, {"letra": "B", "texto": "ABAFAMENTO", "imagem_url": null}, {"letra": "C", "texto": "RESFRIAMENTO", "imagem_url": null}, {"letra": "D", "texto": "ISOLAMENTO", "imagem_url": null}]'::jsonb, 'C', null),
('anac', '1599f67f-0038-45e9-9a25-eab3b31633d3', 'Segurança e Emergência', null, 'A FREQÜÊNCIA DO EQUIPAMENTO RÁDIO-TRANSMISSOR DE EMERGÊNCIA É:', null, '[{"letra": "A", "texto": "121,5 MHz", "imagem_url": null}, {"letra": "B", "texto": "125,1 MHz", "imagem_url": null}, {"letra": "C", "texto": "212,5 MHz", "imagem_url": null}, {"letra": "D", "texto": "215 MHz", "imagem_url": null}]'::jsonb, 'A', null),
('anac', '72aa9a12-1e5d-4345-9f20-4dca9aa1572f', 'Segurança e Emergência', null, 'EM UMA SOBREVIVÊNCIA NA SELVA, PARA QUE SE POSSA COMER O BROTO DA SAMAMBAIA, DEVE-SE FERVÊ-LO POR 10 MINUTOS E DEPOIS', null, '[{"letra": "A", "texto": "FERVÊ-LO EM OUTRA ÁGUA, POR MAIS 40 MINUTOS", "imagem_url": null}, {"letra": "B", "texto": "ASSÁ-LO SOB PEDRAS", "imagem_url": null}, {"letra": "C", "texto": "FERVÊ-LO EM ÁGUA SALGADA, POR 5 MINUTOS", "imagem_url": null}, {"letra": "D", "texto": "FRITÁ-LO COM GORDURA VEGETAL", "imagem_url": null}]'::jsonb, 'A', null),
('anac', '19d6481c-0b01-41ee-88a8-3fcdbb449491', 'Segurança e Emergência', null, 'DEVE-SE UTILIZAR O PIROTÉCNICO FORA DO BOTE NA POSIÇÃO:', null, '[{"letra": "A", "texto": "vertical, a favor do vento", "imagem_url": null}, {"letra": "B", "texto": "horizontal, contra o vento", "imagem_url": null}, {"letra": "C", "texto": "vertical, contra o vento", "imagem_url": null}, {"letra": "D", "texto": "horizontal, a favor do vento", "imagem_url": null}]'::jsonb, 'D', null),
('anac', '06a577e5-3738-4db6-b1a4-c31ff5387173', 'Segurança e Emergência', null, 'EXISTEM COMBUSTÍVEIS QUE PELA SUA GRANDE VELOCIDADE DE QUEIMA, CRIAM UMA ENORME PRODUÇÃO DE GASES E QUANDO INFLAMADOS EM COMPARTIMENTOS FECHADOS PRODUZEM O FENÔMENO DA:', null, '[{"letra": "A", "texto": "eletricidade estática", "imagem_url": null}, {"letra": "B", "texto": "explosão", "imagem_url": null}, {"letra": "C", "texto": "irradiação", "imagem_url": null}, {"letra": "D", "texto": "ignição", "imagem_url": null}]'::jsonb, 'B', null),
('anac', 'd61ff1dd-7e05-4b75-875a-6d54446741a5', 'Segurança e Emergência', null, 'PROCESSO PELO QUAL UM EMISSOR ORGANIZA UMA IDEIA, DE FORMA RACIONAL E COERENTE, ATRAVÉS DE UM CONJUNO DE CÓDIGOS COMPARTILHADOS, PARA TRANSMITIR INFORMAÇÕES, PODE SER A DEFINIÇÃO DE', null, '[{"letra": "A", "texto": "COMPORTAMENTO", "imagem_url": null}, {"letra": "B", "texto": "COMUNICAÇÃO", "imagem_url": null}, {"letra": "C", "texto": "CONHECIMENTO", "imagem_url": null}, {"letra": "D", "texto": "CONFLITO", "imagem_url": null}]'::jsonb, 'B', null),
('anac', '4cb061f2-9b8b-403c-be70-aa5de60878d6', 'Segurança e Emergência', null, 'A EVACUAÇÃO DA AERONAVE, APÓS UM POUSO DE EMERGÊNCIA NO MAR, DEVERÁ SER INICIADA;', null, '[{"letra": "A", "texto": "assim que a aeronave tocar na água", "imagem_url": null}, {"letra": "B", "texto": "quando todos estiverem prontos", "imagem_url": null}, {"letra": "C", "texto": "quando o avião estiver totalmente parado", "imagem_url": null}, {"letra": "D", "texto": "quando o bote estiver armado", "imagem_url": null}]'::jsonb, 'C', null),
('anac', '8e41e1a6-92e4-40c6-ba95-d23c6c4888e5', 'Segurança e Emergência', null, 'NUMA SOBREVIVÊNCIA NA SELVA PODE-SE FAZER FOGÃO MONTANDO A 50 CM ACIMA DA FOGUEIRA, FORMANDO UM TRIPÉ QUE É CHAMADO DE:', null, '[{"letra": "A", "texto": "trincheira", "imagem_url": null}, {"letra": "B", "texto": "forno de lenha", "imagem_url": null}, {"letra": "C", "texto": "forno de barro", "imagem_url": null}, {"letra": "D", "texto": "moquém", "imagem_url": null}]'::jsonb, 'D', null),
('anac', '961ec8a0-9ade-4796-bdca-3c70fead2e83', 'Segurança e Emergência', null, 'UTILIZANDO-SE O MÉTODO DA ESTAQUINHA PARA A DETERMINAÇÃO DO MEIO-DIA LOCAL, ATRAVÉS DA SOMBRA, OBTÉM-SE TAMBÉM A INFORMAÇÃO REFERENTE À', null, '[{"letra": "A", "texto": "LINHA NORTE-SUL", "imagem_url": null}, {"letra": "B", "texto": "LONGITUDE LOCAL", "imagem_url": null}, {"letra": "C", "texto": "LINHA LESTE-OESTE", "imagem_url": null}, {"letra": "D", "texto": "LATITUDE LOCAL", "imagem_url": null}]'::jsonb, 'A', null),
('anac', 'e179d6f4-6d0f-42dc-9679-7d49d97fc66e', 'Segurança e Emergência', null, 'O CORANTE MARCADOR D''ÁGUA É UM RECURSO UTILIZADO PARA SE FAZER SINALIZAÇÃO:', null, '[{"letra": "A", "texto": "apenas durante o dia", "imagem_url": null}, {"letra": "B", "texto": "diurna e noturna", "imagem_url": null}, {"letra": "C", "texto": "noturna quando se ouvir ruído de aeronave", "imagem_url": null}, {"letra": "D", "texto": "apenas durante a noite", "imagem_url": null}]'::jsonb, 'A', null),
('anac', 'f45b805d-ad44-454a-9087-121fd6afd579', 'Segurança e Emergência', null, 'NUMA AERONAVE, DENTRE OS EQUIPAMENTOS AUXILIARES DE EVACUAÇÃO DAS PORTAS, PODEMOS CITAR', null, '[{"letra": "A", "texto": "ESCADAS EXTERNAS", "imagem_url": null}, {"letra": "B", "texto": "ESCORREGADEIRAS", "imagem_url": null}, {"letra": "C", "texto": "CORRIMÕES INFLÁVEIS", "imagem_url": null}, {"letra": "D", "texto": "TIRAS DE SUSTENTAÇÃO", "imagem_url": null}]'::jsonb, 'B', null),
('anac', 'af18f115-56df-48b8-8573-ab1d91152b00', 'Segurança e Emergência', null, 'A NECESSIDADE DE ATENÇÃO CONSTANTE DURANTE POUSOS E DECOLAGENS TEM COMO OBJETIVO:', null, '[{"letra": "A", "texto": "que os paxs notem que o comissário os observa", "imagem_url": null}, {"letra": "B", "texto": "ao controle do painel dianteiro de comissários", "imagem_url": null}, {"letra": "C", "texto": "estar atento caso haja alguma anormalidade", "imagem_url": null}, {"letra": "D", "texto": "verificar se o serviço de bordo não caia dos trolleys", "imagem_url": null}]'::jsonb, 'C', null),
('anac', '3fb28361-df0c-4e0e-9805-0d74f302727d', 'Segurança e Emergência', null, 'NO BOEING 737, EM CASO DE POUSO FORÇADO NO MAR, AS SAÍDAS QUE DEVEM SER USADAS SÃO AS:', null, '[{"letra": "A", "texto": "portas dianteiras", "imagem_url": null}, {"letra": "B", "texto": "portas traseiras", "imagem_url": null}, {"letra": "C", "texto": "que estiverem acima do nível da água", "imagem_url": null}, {"letra": "D", "texto": "qualquer uma, todas são operativas", "imagem_url": null}]'::jsonb, 'C', null)
