('anac', 'ca242273-27ed-49eb-b794-a76751c033c7', 'Segurança e Emergência', null, 'NAS P.S.U. DAS AERONAVES EXISTE SEMPRE UMA MÁSCARA EXTRA EM RELAÇÃO AO NÚMERO DE POLTRONAS, POIS,', null, '[{"letra": "A", "texto": "PODERÁ EXISTIR PASSAGEIRO COLO, E SERVIRÁ TAMBÉM PARA COMISSÁRIOS", "imagem_url": null}, {"letra": "B", "texto": "UMA DELAS PODERÁ SER USADA COM FINS TERAPÊUTICOS, DEIXANDO AS OUTRAS INTACTAS", "imagem_url": null}, {"letra": "C", "texto": "FACILITA A ACOMODAÇÃO DAS MESMAS NO COMPARTIMENTO", "imagem_url": null}, {"letra": "D", "texto": "EM CASO DE FALHA UMA RESERVA JÁ ESTARÁ AO ALCANCE", "imagem_url": null}]'::jsonb, 'A', null),
('anac', '6b77f089-edee-4491-b0a1-bf11a32045d4', 'Segurança e Emergência', null, 'ENCONTRANDO-SE BROTOS DE COCO, CAÍDOS NO CHÃO,  GERMINANDO:', null, '[{"letra": "A", "texto": "não devem ser ingeridos, pois, podem ser venenosos", "imagem_url": null}, {"letra": "B", "texto": "podem ser comidos e têm sabor de aipo", "imagem_url": null}, {"letra": "C", "texto": "deve-se ter cuidado; algumas espécies são venenosas", "imagem_url": null}, {"letra": "D", "texto": "somente podem ser ingeridos, após o teste do paladar", "imagem_url": null}]'::jsonb, 'B', null),
('anac', '6b63c4cc-9a90-4e48-800b-36a14d418e50', 'Segurança e Emergência', null, 'PODE-SE ENCONTRAR AERONAVES BOEING 737, SAÍDAS DE EMERGÊNCIA COM ESCAPE SLIDE:', null, '[{"letra": "A", "texto": "8", "imagem_url": null}, {"letra": "B", "texto": "10", "imagem_url": null}, {"letra": "C", "texto": "6", "imagem_url": null}, {"letra": "D", "texto": "4", "imagem_url": null}]'::jsonb, 'D', null),
('anac', '53eca895-9f2a-4264-a6e8-f2ef349b68e6', 'Segurança e Emergência', null, 'NA HEMISFÉRIO SUL, OS SOBREVIVENTES PODERÃO ORIENTAR-SE PELA CONSTELAÇÃO:', null, '[{"letra": "A", "texto": "Usar Maior", "imagem_url": null}, {"letra": "B", "texto": "Cassiopéia", "imagem_url": null}, {"letra": "C", "texto": "Cruzeiro do Sul", "imagem_url": null}, {"letra": "D", "texto": "de Andrômeda", "imagem_url": null}]'::jsonb, 'C', null),
('anac', 'fa251445-31f5-4b86-ace5-b7c2431cd156', 'Segurança e Emergência', null, 'O MÉTODO MAIS FÁCIL E EFICAZ DE FAZER FOGO, SEM O AUXÍLIO DE FÓSFOROS, É USAR UMA PEDRA QUE, ATRITADA COM AÇO, PRODUZ FAÍSCA. NESTE CASO, USA-SE UMA PEDERNEIRA OU ROCHA', null, '[{"letra": "A", "texto": "DURA", "imagem_url": null}, {"letra": "B", "texto": "CALCÁRIA", "imagem_url": null}, {"letra": "C", "texto": "MACIA", "imagem_url": null}, {"letra": "D", "texto": "AMOLAR", "imagem_url": null}]'::jsonb, 'A', null),
('anac', 'cc48cb97-532a-4060-85b5-beb30d1e1f03', 'Segurança e Emergência', null, 'OS EQUIPAMENTOS COLETIVOS DE FLUTUAÇÃO POSSUEM UM COMPONENTE DE GRANDE IMPORTÂNCIA, QUE RETARDA A DERIVA DA EMBARCAÇÃO, QUE É O (A):', null, '[{"letra": "A", "texto": "biruta d água", "imagem_url": null}, {"letra": "B", "texto": "mastro inflável", "imagem_url": null}, {"letra": "C", "texto": "leme direcional", "imagem_url": null}, {"letra": "D", "texto": "bujão de vedação", "imagem_url": null}]'::jsonb, 'A', null),
('anac', '55aaf887-11db-424e-8a66-e1809f75b0f4', 'Segurança e Emergência', null, 'DURANTE UMA SOBREVIVÊNCIA NO MAR, DENTRE OUTRAS COISAS, A BIRUTA D´ÁGUA SERVIRÁ PARA,', null, '[{"letra": "A", "texto": "ARMAZENAR A ÁGUA DISPONÍVEL NO BOTE", "imagem_url": null}, {"letra": "B", "texto": "PURIFICAR A ÀGUA DO MAR", "imagem_url": null}, {"letra": "C", "texto": "MANTER O BOTE PRÓXIMO AO LUGAR DO ACIDENTE", "imagem_url": null}, {"letra": "D", "texto": "DESTILAR E DESSALGAR A ÁGUA DO MAR", "imagem_url": null}]'::jsonb, 'C', null),
('anac', 'e3baedd2-bb3a-4fe6-8325-68fbb03937ab', 'Segurança e Emergência', null, 'O FOGO QUE QUEIMA EM SUPERFÍCIE E EM PROFUNDIDADE, DEIXANDO RESÍDUOS AO FINAL DO PROCESSO É O DE CLASSE', null, '[{"letra": "A", "texto": "A", "imagem_url": null}, {"letra": "B", "texto": "D", "imagem_url": null}, {"letra": "C", "texto": "C", "imagem_url": null}, {"letra": "D", "texto": "B", "imagem_url": null}]'::jsonb, 'A', null),
('anac', '360305ad-705e-4c31-8170-297fe4514149', 'Segurança e Emergência', null, 'NO CHEQUE PRÉ-VOO DO MEGAFONE, DEVE-SE VERIFICAR SEU (SUA)', null, '[{"letra": "A", "texto": "INVÓLUCRO E LOCALIZAÇÃO", "imagem_url": null}, {"letra": "B", "texto": "FUNCIONAMENTO E LACRE", "imagem_url": null}, {"letra": "C", "texto": "MANÔMETRO E FIXAÇÃO", "imagem_url": null}, {"letra": "D", "texto": "FIXAÇÃO E SINAL SONORO", "imagem_url": null}]'::jsonb, 'D', null),
('anac', '80a6f071-d8d5-4c56-ba2e-6aea769646fb', 'Legislação Aeronáutica', null, 'A CRIAÇÃO DO SISTEMA DE AVIAÇÃO CIVIL, PELO MINISTÉRIO DA AERONÁUTICA, FOI INSTITUÍDA PELO DECRETO Nº:', null, '[{"letra": "A", "texto": "65.144, de 12 set 69", "imagem_url": null}, {"letra": "B", "texto": "65.143, de 12 jan 79", "imagem_url": null}, {"letra": "C", "texto": "66.148, de 12 dez 70", "imagem_url": null}, {"letra": "D", "texto": "65.145, de 12 set 69", "imagem_url": null}]'::jsonb, 'A', null),
('anac', 'ac55c1dd-862a-46e4-9453-f83e28a3eb40', 'Segurança e Emergência', null, 'ENCONTRANDO-SE OSTRAS E MARISCOS, A MELHOR FORMA DE LAVÁ-LOS É:', null, '[{"letra": "A", "texto": "jogando-os em água fervente", "imagem_url": null}, {"letra": "B", "texto": "lavando-os em água fria e corrente", "imagem_url": null}, {"letra": "C", "texto": "retirar as cascas uma a uma; verificar se não estão deteriorados; depois de lavá-los em água purificada, cozinhá-los por 30 minutos", "imagem_url": null}, {"letra": "D", "texto": "deixando-os dentro de uma vasilha com água durante a noite; no dia seguinte estão limpos, pois eles se limpam sozinhos", "imagem_url": null}]'::jsonb, 'D', null),
('anac', 'db5be807-3e33-4d29-8ab2-ce6d0da50abe', 'Segurança e Emergência', null, 'AS TRILHAS DE ANIMAIS PODERÃO CONDUZIR OS SOBREVIVENTES A UM(A):', null, '[{"letra": "A", "texto": "correntes ou nascentes de água", "imagem_url": null}, {"letra": "B", "texto": "caverna que servirá como abrigo", "imagem_url": null}, {"letra": "C", "texto": "clareira onde poderão ser feitas sinalizações visíveis", "imagem_url": null}, {"letra": "D", "texto": "local onde estão os filhotes e onde serão mais facilmente caçados", "imagem_url": null}]'::jsonb, 'A', null),
('anac', 'f79417c3-0fdc-40a6-a4e2-3531f112c7b7', 'Legislação Aeronáutica', null, 'NO QUE DIZ RESPEITO A REMUNERAÇÃO, ASSINALE A ALTERNATIVA CORRETA', null, '[{"letra": "A", "texto": "A REMUNERAÇÃO DOS TRIPULANTES SERÁ EXCLUSIVAMENTE PAGA EM PARCELA FIXA", "imagem_url": null}, {"letra": "B", "texto": "INTEGRAM A REMUNERAÇÃO DOS TRIPULANTES, A AJUDA DE CUSTO E AS DIÁRIAS DE HOSPEDAGEM", "imagem_url": null}, {"letra": "C", "texto": "NÃO INTEGRAM A REMUNERAÇÃO DOS TRIPULANTES A IMPORTÂNCIA PAGA A TÍTULO DE FÉRIAS", "imagem_url": null}, {"letra": "D", "texto": "O PERÍODO DE TEMPO DE SOLO ENTRE ETAPAS DE UM VOO EM UMA MESMA JORNADA SERÁ REMUNERADO", "imagem_url": null}]'::jsonb, 'D', null),
('anac', '3a796aa8-0bb2-4c7d-a024-7dc985a492a2', 'Legislação Aeronáutica', null, 'AS AUTORIDADES AERONÁUTICAS DA AMÉRICA DO SUL, CENTRAL E CARIBE, DISPÕE DE UMA ORGANIZAÇÃO ADEQUADA, PARA TRATAR DE ASSUNTOS RELATIVOS A AVIAÇÃO CIVIL LATINO AMERICANA, DENOMINADA:', null, '[{"letra": "A", "texto": "CLAC", "imagem_url": null}, {"letra": "B", "texto": "ICAO", "imagem_url": null}, {"letra": "C", "texto": "IATA", "imagem_url": null}, {"letra": "D", "texto": "ALTA", "imagem_url": null}]'::jsonb, 'A', null),
('anac', '723427fd-cba2-4cbd-8879-8135ab344cf6', 'Legislação Aeronáutica', null, 'NO QUE DIZ RESPEITO A DURAÇÃO DO TRABALHO DO TRIPULANTE, ASSINALE A ALTERNATIVA CORRETA', null, '[{"letra": "A", "texto": "SERÁ OBSERVADO O LIMITE MÁXIMO DE 3 MADRUGADAS CONSECUTIVAS DE TRABALHO", "imagem_url": null}, {"letra": "B", "texto": "AOS TRIPULANTES QUE TAMBÉM EXERÇAM ATIVIDADES ADMINISTRATIVAS, OS LIMITES SERÃO ALTERADOS, SEM PREVISÃO DE HORAS ESTABELECIDAS", "imagem_url": null}, {"letra": "C", "texto": "ENTENDE-SE COMO MADRUGADA O PERIODO TRANSCORRIDO ENTRE 0 (ZERO) E 6 (SEIS) HORAS, TOTAL OU PARCIALMENTE, CONSIDERADO O FUSO HORARIO DA BASE CONTRATUAL", "imagem_url": null}, {"letra": "D", "texto": "É PERMITIDA A ALTERAÇÃO, MEDIANTE CONVENÇÃO OU ACORDO COLETIVO, DOS LIMITES SEMANAIS E MENSAIS DE TRABALHO", "imagem_url": null}]'::jsonb, 'C', null),
('anac', '6e410b09-870f-4cc2-a199-c0162a68c478', 'Legislação Aeronáutica', null, 'O TRANSPORTE QUE, POR MOTIVO DE FORÇA MAIOR, FIZER ESCALA EM TERRITÓRIO ESTRANGEIRO, ESTANDO, PORÉM, EM TERRITÓRIO BRASILEIRO OS SEUS PONTOS DE PARTIDA E DESTINO, É CONSIDERADO TRANSPORTE:', null, '[{"letra": "A", "texto": "doméstico", "imagem_url": null}, {"letra": "B", "texto": "aéreo regular", "imagem_url": null}, {"letra": "C", "texto": "brasileiro", "imagem_url": null}, {"letra": "D", "texto": "nacional", "imagem_url": null}]'::jsonb, 'A', null),
